function snap(v){return Math.round(v);}
/* ===== UNLOCK KARAKTER: mulai 5, +5 tiap 10 stage (urutan = urutan daftar hero) ===== */
const UNLOCK_START=5,UNLOCK_EVERY=5,UNLOCK_COUNT=5,STAGE_KEY='eternal_rift_max_stage_v1';
let maxStageReached=1;
try{maxStageReached=Math.max(1,parseInt(localStorage.getItem(STAGE_KEY),10)||1);const _sv=JSON.parse(localStorage.getItem('eclipse_rpg_manual_save_v2')||'null');if(_sv&&_sv.stageIndex>=0)maxStageReached=Math.max(maxStageReached,_sv.stageIndex+1);}catch(e){}
function unlockedCharCount(ms){return Math.min(Object.keys(CHARACTERS).length,UNLOCK_START+Math.floor(ms/UNLOCK_EVERY)*UNLOCK_COUNT);}
function charIndexOf(id){return Object.keys(CHARACTERS).indexOf(id);}
function unlockStageFor(i){return i<UNLOCK_START?1:Math.ceil((i-UNLOCK_START+1)/UNLOCK_COUNT)*UNLOCK_EVERY;}
function isCharUnlocked(id){const i=charIndexOf(id);return i>=0&&i<unlockedCharCount(maxStageReached);}
function markStageReached(n){if(!(n>maxStageReached))return;const o=unlockedCharCount(maxStageReached);maxStageReached=n;try{localStorage.setItem(STAGE_KEY,String(n));}catch(e){}const k=unlockedCharCount(n)-o;if(k>0){try{deferGameplayToast('🔓 '+k+' karakter baru terbuka!',2600);}catch(_e){}}}
let _rsLast=0;function realStep(dt){const n=performance.now(),d=_rsLast?(n-_rsLast)/1000:dt;_rsLast=n;return(d>0&&d<.5)?d:dt;}
function pxRect(g,x,y,w,h,color){g.fillStyle=color;g.fillRect(snap(x),snap(y),Math.max(1,snap(w)),Math.max(1,snap(h)));}

const SK='eclipse_rpg_settings_v1';
const DS={shake:1,showDamage:true,showAimLine:true,particles:1,shader:1,performance:'auto',difficulty:1,sound:1,music:1,hudSafe:0,uiText:1,hiContrast:false,colorBlind:false,holdMs:0};
let settings={...DS};
let performanceQuality='medium',adaptiveFrameMs=16.7,adaptiveLowTime=0,adaptiveHighTime=0;
function loadSettings(){try{const r=localStorage.getItem(SK);if(r)settings={...DS,...JSON.parse(r)};if(!['auto','low','medium','high'].includes(settings.performance))settings.performance='auto';setPerformanceQuality(settings.performance==='auto'?(((navigator.hardwareConcurrency||8)<=4||(navigator.deviceMemory||8)<=2)?'low':'medium'):settings.performance);}catch(e){}}
function saveSettings(){try{localStorage.setItem(SK,JSON.stringify(settings));}catch(e){}}
function getPerformanceRank(){return performanceQuality==='low'?0:performanceQuality==='high'?2:1;}
function getParticleLimit(){const rank=getPerformanceRank();return rank===0?180:rank===2?560:340;}
function getCosmeticScale(){const rank=getPerformanceRank();return rank===0?0.35:rank===2?1:0.65;}
function setPerformanceQuality(quality){if(quality===performanceQuality)return;performanceQuality=quality;}
function updateAdaptivePerformance(frameMs){
  if(settings.performance!=='auto'||!running)return;
  adaptiveFrameMs+=(frameMs-adaptiveFrameMs)*.12;
  if(adaptiveFrameMs>18.5){adaptiveLowTime+=frameMs/1000;adaptiveHighTime=0;}
  else if(adaptiveFrameMs<17.6){adaptiveHighTime+=frameMs/1000;adaptiveLowTime=Math.max(0,adaptiveLowTime-frameMs/1000);}
  else{adaptiveLowTime=Math.max(0,adaptiveLowTime-frameMs/1000);adaptiveHighTime=0;}
  if(adaptiveLowTime>=.75&&performanceQuality!=='low'){
    setPerformanceQuality(performanceQuality==='high'?'medium':'low');
    adaptiveLowTime=0;adaptiveHighTime=0;
  }else if(adaptiveHighTime>=4&&performanceQuality!=='high'){
    setPerformanceQuality(performanceQuality==='low'?'medium':'high');
    adaptiveHighTime=0;adaptiveLowTime=0;
  }
}
function renderSettingsUI(){document.querySelectorAll('[data-setting]').forEach(el=>{const k=el.getAttribute('data-setting'),cv=String(settings[k]);el.querySelectorAll('button').forEach(btn=>{const v=btn.getAttribute('data-value');btn.classList.toggle('active',v===cv);btn.onclick=()=>{let nv=v;if(v==='true')nv=true;else if(v==='false')nv=false;else if(k!=='performance'&&!isNaN(parseFloat(v))&&isFinite(v))nv=parseFloat(v);settings[k]=nv;if(k==='performance'&&nv!=='auto')setPerformanceQuality(nv);saveSettings();if(k==='hudSafe')fitGameToScreen();renderSettingsUI();if(k==='showAimLine'&&!nv)currentAimTarget=null;};});});}

/* ============================================================
   ARCHETYPE DETECTION
   ============================================================ */
function getArchetype(ch){
  const n=(ch.name||'').toUpperCase();
  const s=(ch.sub||'').toUpperCase();
  const style=ch.style||'';
  if(/ROBOT|MECH|ANDROID|CYBORG|MECHA|DRONE|TINKER/.test(n)) return 'robot';
  if(/DRAGON (KNIGHT|SLAYER|TAMER|QUEEN|RIDER)/.test(n)) return 'dragonrider';
  if(/WOLF (RIDER|KING)/.test(n)) return 'wolfrider';
  if(/BEAST ?(MASTER|TAMER)/.test(n)) return 'beastmaster';
  if(/TAMER/.test(n)) return 'beastmaster';
  if(/ANGEL|SERAPH/.test(n)) return 'angel';
  if(/DEMON|DEVIL|LORD/.test(n) && /DEMON|DEVIL/.test(n)) return 'demon';
  if(/LICH|UNDEAD|NECROMANCER|SOUL EATER|SOUL HUNTER|REAPER/.test(n)) return 'undead';
  if(/GHOST|SPIRIT|WRAITH|PHANTOM|SHADOW|BANSHEE/.test(n)) return 'ghost';
  if(/PHOENIX/.test(n)) return 'phoenix';
  if(/ICE QUEEN|SNOW/.test(n)) return 'icequeen';
  if(/GOLEM|TITAN|COLOSSUS/.test(n)) return 'golem';
  if(/LIGHT KING|DARK KING|RULER|EMPEROR|QUEEN|KING/.test(n)) return 'royal';
  if(/NINJA|ASSASSIN|ROGUE|THIEF|RONIN/.test(n)) return 'ninja';
  if(/MAGE|WIZARD|WARLOCK|SORCERER|ORACLE|ARCANIST|CHRONOMANCER|ELEMENTALIST/.test(n)) return 'mage';
  if(/SUMMONER|CALLER|KEEPER/.test(n)) return 'summoner';
  if(/PIRATE|VIKING|AXEMAN|WARLORD|GLADIATOR/.test(n)) return 'warrior';
  if(/PRIEST|PALADIN|CRUSADER|SUN KNIGHT|HOLY/.test(n)) return 'paladin';
  if(style==='mage') return 'mage';
  if(style==='ranger'||style==='bard') return 'ranger';
  if(style==='rogue') return 'ninja';
  if(style==='monk') return 'monk';
  if(style==='engineer') return 'robot';
  if(style==='paladin') return 'paladin';
  if(style==='warlord') return 'warrior';
  return 'human';
}

function drawHeroPixelOutline(g,arch){
  const ink='#101522';
  if(arch==='dragonrider'||arch==='wolfrider'){
    pxRect(g,-24,-8,48,22,ink);
    pxRect(g,-13,-24,26,18,ink);
    pxRect(g,-10,-39,20,18,ink);
    pxRect(g,-15,-14,7,15,ink);pxRect(g,8,-14,7,15,ink);
    pxRect(g,-12,10,8,10,ink);pxRect(g,4,10,8,10,ink);
    return;
  }
  if(arch==='robot'||arch==='golem'||arch==='royal'||arch==='icequeen'){
    const wide=arch==='golem'?15:13;
    pxRect(g,-9,10,8,10,ink);pxRect(g,1,10,8,10,ink);
    pxRect(g,-wide,-11,wide*2,22,ink);
    pxRect(g,-wide-3,-8,5,16,ink);pxRect(g,wide-2,-8,5,16,ink);
    pxRect(g,-12,-30,24,22,ink);
    pxRect(g,-8,-35,16,10,ink);
    return;
  }
  if(arch==='mage'||arch==='summoner'||arch==='ninja'||arch==='paladin'){
    pxRect(g,-10,8,9,12,ink);pxRect(g,1,8,9,12,ink);
    pxRect(g,-12,-9,24,20,ink);
    pxRect(g,-13,-2,26,15,ink);
    pxRect(g,-6,-28,12,18,ink);
    pxRect(g,-16,-4,6,13,ink);pxRect(g,10,-4,6,13,ink);
    return;
  }
  const wide=arch==='monk'?11:12;
  pxRect(g,-9,8,8,12,ink);pxRect(g,1,8,8,12,ink);
  pxRect(g,-wide,-8,wide*2,20,ink);
  pxRect(g,-wide-3,-6,5,13,ink);pxRect(g,wide-2,-6,5,13,ink);
  pxRect(g,-12,-24,24,18,ink);
}

