function trpgCharOf(e){
  if(e._tc!==undefined)return e._tc;
  const def=ET[e.et];
  return e._tc=(def&&!def.boss&&ETS[e.et])||null;
}
function trpgSheet(key,deg){
  const c=TRPG[key];deg=((Math.round(deg||0)%360)+360)%360;
  if(!deg)return c.img;
  let cv=c.cache.get(deg);if(cv)return cv;
  cv=document.createElement('canvas');cv.width=c.img.width;cv.height=c.img.height;
  const cx=cv.getContext('2d',{willReadFrequently:true});cx.drawImage(c.img,0,0);
  const im=cx.getImageData(0,0,cv.width,cv.height),d=im.data;
  for(let o=0;o<d.length;o+=4){
    if(!d[o+3])continue;
    const r=d[o]/255,g=d[o+1]/255,b=d[o+2]/255,mx=Math.max(r,g,b),mn=Math.min(r,g,b),df=mx-mn,l=(mx+mn)/2;
    if(df<.04)continue;
    const s=df/(1-Math.abs(2*l-1));
    let h=mx===r?((g-b)/df)%6:mx===g?(b-r)/df+2:(r-g)/df+4;
    h=(((h*60+deg)%360)+360)%360;
    const cc=(1-Math.abs(2*l-1))*s,x=cc*(1-Math.abs((h/60)%2-1)),m=l-cc/2;
    let rr=0,gg=0,bb=0;
    if(h<60){rr=cc;gg=x;}else if(h<120){rr=x;gg=cc;}else if(h<180){gg=cc;bb=x;}else if(h<240){gg=x;bb=cc;}else if(h<300){rr=x;bb=cc;}else{rr=cc;bb=x;}
    d[o]=(rr+m)*255;d[o+1]=(gg+m)*255;d[o+2]=(bb+m)*255;
  }
  cx.putImageData(im,0,0);c.cache.set(deg,cv);return cv;
}
/* state animasi bersama: idle / walk / atk / hurt (dipicu dari state game) */
function trpgState(e,na){
  const now=worldTime;let st=e._ta;
  if(!st)st=e._ta={s:'idle',t0:now,fx:player.x>=e.x?1:-1,lx:e.x,ly:e.y,lt:now,v:0,ac:e.attackCd,sf:e.skillFlash||0,ht:e.hit,n:0,k:0,off:Math.random()*5,age:0,m:false};
  const dtw=now-st.lt;
  if(dtw>0){st.v=st.v*.6+Math.min(Math.hypot(e.x-st.lx,e.y-st.ly)/dtw,400)*.4;st.lx=e.x;st.ly=e.y;st.lt=now;}
  if(Math.abs(player.x-e.x)>4)st.fx=player.x>e.x?1:-1;
  const atk=e.attackCd>st.ac+.15||(e.skillFlash||0)>st.sf+.2,hurt=e.hit>st.ht+.05;
  st.ac=e.attackCd;st.sf=e.skillFlash||0;st.ht=e.hit;
  if(atk){st.s='atk';st.t0=now;st.n++;st.k=st.n%na;}
  else if(hurt&&st.s!=='atk'){st.s='hurt';st.t0=now;}
  st.age=now-st.t0;
  if((st.s==='atk'&&st.age>.32)||(st.s==='hurt'&&st.age>.2))st.s='idle';
  st.m=st.v>10&&e.stun<=0;
  return st.s==='idle'?(st.m?'walk':'idle'):st.s;
}
/* Pipoya: ilustrasi statis, digerakkan secara prosedural */
function pipPose(idx,mode,st,t){
  const fly=PIP.fly[idx];let ox=0,oy=fly?-7+Math.sin(t*3)*2.5:Math.sin(t*3),rot=0,sx=1,sy=1;
  if(mode==='walk'){if(fly){oy+=Math.sin(t*10)*2;rot=Math.sin(t*6)*.08;}else{const b=Math.abs(Math.sin(t*9));oy-=b*5;rot=Math.sin(t*9)*.07;sy=1+b*.05;}}
  else if(mode==='atk'){const L=Math.sin(Math.min(1,st.age/.32)*Math.PI);ox=st.fx*L*9;oy-=L*3;sx=1+L*.15;sy=1-L*.1;}
  else if(mode==='hurt')ox=Math.sin(st.age*70)*3;
  return [ox,oy,rot,sx,sy];
}
function pipDraw(idx,pose,Hh,alpha,flash){
  const [w,h]=PIP.n[idx],cl=PIP.cell,H2=Hh*1.1,k=Math.min(H2/h,H2*1.6/w),dw=w*k,dh=h*k,sx=(idx%PIP.cols)*cl,sy=Math.floor(idx/PIP.cols)*cl;
  ctx.save();ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.globalAlpha=alpha;
  ctx.translate(pose[0],Hh/2+pose[1]);ctx.rotate(pose[2]);ctx.scale(pose[3],pose[4]);
  ctx.drawImage(PIP.img,sx,sy,w,h,-dw/2,-dh,dw,dh);
  if(flash){ctx.globalCompositeOperation='lighter';ctx.globalAlpha=flash;ctx.drawImage(PIP.img,sx,sy,w,h,-dw/2,-dh,dw,dh);}
  ctx.restore();
}
function drawTrpgEnemy(e){
  {const _nc=naCfgOf(e);if(_nc&&naDrawEnemy(e,_nc))return true;}
  const key=trpgCharOf(e);if(!key)return false;
  const Hh=Math.max(30,e.r*1.9);
  if(key[0]==='p'){
    if(!PIP.ready)return false;
    const st={},m=trpgState(e,1),s=e._ta;
    pipDraw(+key.slice(1),pipPose(+key.slice(1),m,s,worldTime+s.off),Hh,1,e.hit>0?.45:0);
    return true;
  }
  const ch=TRPG[key];if(!ch.ready)return false;
  const mode=trpgState(e,ch.atk.length),st=e._ta;
  let rn,f;
  if(mode==='atk'){rn=ch.atk[st.k];f=Math.min(rn[1]-1,1+Math.floor(st.age/.32*(rn[1]-1)));}
  else if(mode==='hurt'){rn=ch.hurt;f=Math.min(rn[1]-1,Math.floor(st.age/.05));}
  else if(mode==='walk'){rn=ch.walk;f=Math.floor((worldTime+st.off)/.085)%rn[1];}
  else{rn=ch.idle;f=Math.floor((worldTime+st.off)/.14)%rn[1];}
  const fs=ch.fs,sc=Hh/ch.bodyH,sheet=trpgSheet(key,e.th),dx=-ch.cx*sc,dy=Hh/2-ch.fy*sc;
  ctx.save();ctx.imageSmoothingEnabled=false;ctx.scale(ch.flip?st.fx:1,1);
  ctx.drawImage(sheet,f*fs,rn[0]*fs,fs,fs,dx,dy,fs*sc,fs*sc);
  if(e.hit>0){ctx.globalCompositeOperation='lighter';ctx.globalAlpha=.45;ctx.drawImage(sheet,f*fs,rn[0]*fs,fs,fs,dx,dy,fs*sc,fs*sc);}
  ctx.restore();
  return true;
}
const trpgCorpses=[];
function spawnTrpgCorpse(e){
  if(naSpawnCorpse(e))return;
  const key=trpgCharOf(e);if(!key)return;
  if(key[0]==='p'?!PIP.ready:!TRPG[key].ready)return;
  if(trpgCorpses.length>40)trpgCorpses.shift();
  trpgCorpses.push({key,x:e.x,y:e.y,r:e.r,th:e.th||0,fx:e._ta?e._ta.fx:(player.x>=e.x?1:-1),t0:worldTime});
}
function drawTrpgCorpses(){
  try{drawNaCorpses();}catch(_){}
  for(let i=trpgCorpses.length-1;i>=0;i--){
    const c=trpgCorpses[i],age=worldTime-c.t0,st=c.key[0]==='p';
    if(age<0||age>(st?.8:1.3)){trpgCorpses.splice(i,1);continue;}
    if(c.x<camX-120||c.x>camX+W+120||c.y<camY-120||c.y>camY+H+120)continue;
    const Hh=Math.max(30,c.r*1.9);
    ctx.save();ctx.translate(Math.round(c.x),Math.round(c.y));
    ctx.globalAlpha=st?Math.max(0,1-age/.8):(age<.8?1:Math.max(0,1-(age-.8)/.5));
    ctx.fillStyle='rgba(0,0,0,.3)';ctx.beginPath();ctx.ellipse(0,16,c.r,5,0,0,Math.PI*2);ctx.fill();
    ctx.globalAlpha=1;
    if(st){const k=1-age*.4;window.__sv=c.sv||null;window.__sph=c.x%6.28;try{pipDraw(+c.key.slice(1),[0,age*10,c.fx*age*1.1,k,k],Hh,Math.max(0,1-age/.8),0);}finally{window.__sv=null;}}
    else{
      const ch=TRPG[c.key],f=Math.min(ch.death[1]-1,Math.floor(age/.1)),fs=ch.fs,sc=Hh/ch.bodyH;
      ctx.globalAlpha=age<.8?1:Math.max(0,1-(age-.8)/.5);ctx.imageSmoothingEnabled=false;ctx.scale(ch.flip?c.fx:1,1);
      ctx.drawImage(trpgSheet(c.key,c.th),f*fs,ch.death[0]*fs,fs,fs,-ch.cx*sc,Hh/2-ch.fy*sc,fs*sc,fs*sc);
    }
    ctx.restore();
  }
}
function trpgIcon(def,size,g){
  try{if(naIcon(def,size,g))return true;}catch(_){}
  if(def.boss)return false;
  if(def._ti===undefined)def._ti=ET.indexOf(def);
  const key=ETS[def._ti];if(!key)return false;
  if(key[0]==='p'){
    if(!PIP.ready)return false;
    const idx=+key.slice(1),[w,h]=PIP.n[idx],s=Math.min((size-8)/w,(size-8)/h),dw=w*s,dh=h*s;
    g.imageSmoothingEnabled=true;
    g.drawImage(PIP.img,(idx%PIP.cols)*PIP.cell,Math.floor(idx/PIP.cols)*PIP.cell,w,h,Math.round((size-dw)/2),Math.round((size-dh)/2),Math.round(dw),Math.round(dh));
    return true;
  }
  const ch=TRPG[key];if(!ch.ready)return false;
  const [sx,sy,sw,sh]=ch.icon,s=Math.min((size-8)/sw,(size-8)/sh),w=sw*s,h=sh*s;
  g.drawImage(trpgSheet(key,def.th),sx,sy,sw,sh,Math.round((size-w)/2),Math.round((size-h)/2),Math.round(w),Math.round(h));
  return true;
}


