let bossMem={sk:0,dash:0,ult:0};
function bossMemLine(){const t=bossMem.sk+bossMem.dash+bossMem.ult;if(t<8)return null;const top=Object.keys(bossMem).sort((a,b)=>bossMem[b]-bossMem[a])[0];
 return({sk:'Kau selalu mengandalkan skillmu. Aku sudah menghafal polanya.',dash:'Kau terus lari dengan dash. Kali ini aku tidak akan membiarkanmu kabur.',ult:'Kau menyimpan ultimatemu lama sekali. Aku sudah siap menahannya.'})[top]||null;}
{const _s1=skill1,_s2=skill2,_u=ultimate;
 skill1=function(){const b=player.skillCd;_s1();if(player.skillCd>b)bossMem.sk++;};
 skill2=function(){const b=player.dashCd;_s2();if(player.dashCd>b)bossMem.dash++;};
 ultimate=function(){const b=player.ultCd;_u();if(player.ultCd>b)bossMem.ult++;};}
