/* ===== AUDIO v23: SFX + musik prosedural (Web Audio, tanpa file aset) ===== */
const AUD={ctx:null,sfx:null,mus:null,noise:null,last:{},voices:0,mood:'calm',step:0,next:0,mixAt:0};
const SFX_GAP={coin:38,gem:38,hit:45,swing:70,shoot:70,kill:55,ui:40,hurt:90,crit:80};
function audEnsure(){
  if(AUD.ctx)return AUD.ctx;
  const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return null;
  const c=new AC();AUD.ctx=c;
  const comp=c.createDynamicsCompressor();comp.threshold.value=-14;comp.ratio.value=6;comp.connect(c.destination);
  AUD.sfx=c.createGain();AUD.sfx.gain.value=.9;AUD.sfx.connect(comp);
  AUD.mus=c.createGain();AUD.mus.gain.value=0;AUD.mus.connect(comp);
  const buf=c.createBuffer(1,c.sampleRate,c.sampleRate),d=buf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;AUD.noise=buf;
  AUD.next=c.currentTime+.1;
  setInterval(audMusicTick,40);
  return c;
}
function audUnlock(){try{const c=audEnsure();if(c&&c.state==='suspended')c.resume();}catch(_e){}}
['pointerdown','keydown','click'].forEach(ev=>addEventListener(ev,audUnlock,true));
document.addEventListener('visibilitychange',()=>{const c=AUD.ctx;if(!c)return;if(document.hidden)c.suspend();else c.resume();});
function aTone(o){
  const c=AUD.ctx,t=(o.at!=null?o.at:c.currentTime+(o.d||0)),dur=o.t||.1,osc=c.createOscillator(),g=c.createGain();
  const v=Math.max(.0002,(o.v||.2)*(o.bus?1:(Number(settings.sound)||0)));
  osc.type=o.w||'sine';osc.frequency.setValueAtTime(o.f,t);
  if(o.f2)osc.frequency.exponentialRampToValueAtTime(Math.max(1,o.f2),t+dur);
  g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(v,t+Math.min(o.a||.008,dur*.6));g.gain.exponentialRampToValueAtTime(.0001,t+dur);
  osc.connect(g);g.connect(o.bus||AUD.sfx);osc.start(t);osc.stop(t+dur+.05);
  if(!o.bus){AUD.voices++;osc.onended=()=>{AUD.voices--;};}
}
function aNoise(o){
  const c=AUD.ctx,t=(o.at!=null?o.at:c.currentTime+(o.d||0)),dur=o.t||.1,src=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();
  const v=Math.max(.0002,(o.v||.2)*(o.bus?1:(Number(settings.sound)||0)));
  src.buffer=AUD.noise;src.loop=true;f.type=o.ft||'lowpass';f.Q.value=o.q||.8;
  f.frequency.setValueAtTime(o.f||1000,t);if(o.f2)f.frequency.exponentialRampToValueAtTime(Math.max(20,o.f2),t+dur);
  g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.0001,t+dur);
  src.connect(f);f.connect(g);g.connect(o.bus||AUD.sfx);src.start(t,Math.random()*.5);src.stop(t+dur+.05);
  if(!o.bus){AUD.voices++;src.onended=()=>{AUD.voices--;};}
}
const SFX_DEF={
  swing:()=>{aNoise({ft:'bandpass',f:900,f2:2600,q:1.2,t:.1,v:.22});},
  shoot:()=>{aTone({w:'square',f:880,f2:420,t:.09,v:.07});},
  hit:()=>{aNoise({f:2200,f2:300,t:.08,v:.25});aTone({f:170,f2:70,t:.07,v:.2});},
  crit:()=>{aNoise({f:3000,f2:400,t:.1,v:.3});aTone({w:'triangle',f:1100,f2:1900,t:.14,v:.14});aTone({f:140,f2:50,t:.1,v:.25});},
  kill:()=>{aTone({w:'triangle',f:520,f2:200,t:.14,v:.14});aNoise({f:1500,f2:200,t:.1,v:.14});},
  bossdie:()=>{aTone({w:'sawtooth',f:220,f2:30,t:1.1,v:.3});aNoise({f:2500,f2:60,t:1.2,v:.35});[523,659,784,1047].forEach((f,i)=>aTone({w:'triangle',f,t:.5,v:.12,d:.25+i*.12}));},
  skill:()=>{aTone({w:'sawtooth',f:260,f2:900,t:.26,v:.13});aTone({f:1200,f2:1900,t:.3,v:.07,d:.05});},
  dash:()=>{aNoise({ft:'highpass',f:2500,f2:500,t:.2,v:.2});},
  ult:()=>{aTone({w:'sawtooth',f:110,f2:1200,t:.7,v:.16});[440,554,659,880].forEach((f,i)=>aTone({f,t:.6,v:.1,d:.1+i*.03}));aNoise({f:600,f2:3000,t:.6,v:.14});},
  hurt:()=>{aTone({w:'sawtooth',f:240,f2:80,t:.2,v:.2});aNoise({f:900,f2:200,t:.12,v:.2});},
  death:()=>{aTone({w:'sawtooth',f:320,f2:35,t:1.2,v:.25});aNoise({f:1200,f2:80,t:1,v:.18});},
  level:()=>{[523,659,784,1047].forEach((f,i)=>aTone({w:'triangle',f,t:.18,v:.16,d:i*.07}));},
  pick:()=>{aTone({f:660,t:.1,v:.14});aTone({f:990,t:.18,v:.14,d:.07});},
  ui:()=>{aTone({w:'square',f:620,f2:480,t:.05,v:.05});},
  buy:()=>{aTone({f:1200,t:.07,v:.12});aTone({f:1700,t:.14,v:.12,d:.06});},
  potion:()=>{aTone({f:380,f2:760,t:.12,v:.14});aTone({f:520,f2:1000,t:.14,v:.12,d:.1});},
  portal:()=>{aTone({f:380,f2:1700,t:.8,v:.13});aTone({w:'triangle',f:760,f2:2200,t:.8,v:.07,d:.1});},
  enter:()=>{aNoise({ft:'bandpass',f:400,f2:3500,q:.8,t:.5,v:.25});aTone({f:900,f2:200,t:.5,v:.12});},
  coin:()=>{aTone({w:'square',f:1500,t:.05,v:.05});aTone({w:'square',f:2000,t:.09,v:.05,d:.04});},
  gem:()=>{aTone({w:'triangle',f:900,f2:1500,t:.09,v:.07});},
  boss:()=>{aTone({w:'sawtooth',f:55,t:1.6,v:.22,a:.4});aTone({w:'sawtooth',f:82.5,t:1.6,v:.14,a:.5});aNoise({f:200,f2:90,t:1.6,v:.3});}
};
function sfx(n){
  try{
    if(!(Number(settings.sound)>0))return;
    const c=AUD.ctx;if(!c||c.state!=='running'||AUD.voices>28)return;
    const now=performance.now();if(now-(AUD.last[n]||0)<(SFX_GAP[n]||30))return;
    AUD.last[n]=now;const fn=SFX_DEF[n];if(fn)fn();
  }catch(_e){}
}
document.addEventListener('click',e=>{try{const b=e.target.closest&&e.target.closest('button');if(!b||b.classList.contains('perkCard')||['attack','skillBtn','dashBtn','ultBtn'].includes(b.id))return;sfx('ui');}catch(_e){}},true);

/* ===== DROP PICKUP v24: gold / XP / potion jatuh di lantai lalu tersedot ===== */
let drops=[];
function grantDrop(d,quiet){
  if(d.t==='gold')totalGold=Math.min(Number.MAX_SAFE_INTEGER,Math.max(0,(Number.isFinite(totalGold)?totalGold:0)+(d.v|0)));
  else if(d.t==='xp'){xp=Math.max(0,Number.isFinite(xp)?xp:0)+d.v;while(Number.isFinite(xp)&&xp>=100)levelUp();}
  else if(d.t==='potion')potions=Math.max(0,potions)+1;
  if(!quiet)sfx(d.t==='gold'?'coin':d.t==='xp'?'gem':'potion');
}
function flushDrops(){const list=drops;drops=[];for(const d of list)grantDrop(d,true);}
function spawnDrops(e,g,x,pot){
  g=Math.max(0,g|0);x=Math.max(0,x|0);
  if(drops.length>110){grantDrop({t:'gold',v:g},true);grantDrop({t:'xp',v:x},true);if(pot)grantDrop({t:'potion',v:1},true);return;}
  const boss=!!e.boss;
  const add=(t,v)=>{const a=Math.random()*Math.PI*2,s=rand(70,190);drops.push({t,v,x:clamp(e.x,12,WORLD.w-12),y:clamp(e.y,12,WORLD.h-12),vx:Math.cos(a)*s,vy:Math.sin(a)*s*.7,z:4,vz:rand(120,210),age:0,ph:Math.random()*6.28,homing:false});};
  const split=(t,total,n)=>{if(total<=0||n<=0)return;const base=Math.floor(total/n);for(let i=0;i<n;i++)add(t,i===0?total-base*(n-1):base);};
  split('gold',g,g<=0?0:(boss?8:Math.min(3,1+Math.floor(g/25))));
  split('xp',x,x<=0?0:(boss?6:Math.min(3,1+Math.floor(x/25))));
  if(pot)add('potion',1);
}
function updateDrops(dt){
  if(!drops.length||dying)return;
  const range=64*(1+(perks.mag||0)*.35);
  for(let i=drops.length-1;i>=0;i--){
    const d=drops[i];d.age+=dt;
    if(!d.homing){
      const fr=Math.pow(.02,dt);d.x+=d.vx*dt;d.y+=d.vy*dt;d.vx*=fr;d.vy*=fr;
      d.x=clamp(d.x,12,WORLD.w-12);d.y=clamp(d.y,12,WORLD.h-12);
      d.z+=d.vz*dt;d.vz-=700*dt;if(d.z<0){d.z=0;d.vz=Math.abs(d.vz)>80?-d.vz*.45:0;}
    }
    const dx=player.x-d.x,dy=player.y-d.y,dist=Math.hypot(dx,dy)||1;
    if(!d.homing&&d.age>.35&&(dist<range||d.age>2.6))d.homing=true;
    if(d.homing){
      const sp=Math.min(900,320+(d.age-.35)*200),step=sp*dt;
      if(step>=dist-player.r){d.x=player.x;d.y=player.y;}else{d.x+=dx/dist*step;d.y+=dy/dist*step;}
      d.z*=.88;
    }
    if(d.age>.25&&Math.hypot(player.x-d.x,player.y-d.y)<=player.r+8){grantDrop(d);drops.splice(i,1);}
  }
}
function drawDrops(){
  if(!drops.length)return;
  const t=worldTime;
  for(const d of drops){
    if(d.x<camX-20||d.x>camX+W+20||d.y<camY-30||d.y>camY+H+20)continue;
    const x=Math.round(d.x),y=Math.round(d.y-d.z+(d.z>0?0:Math.sin(t*4+d.ph)*2));
    ctx.globalAlpha=.3;ctx.fillStyle='#000';ctx.fillRect(x-4,Math.round(d.y)+5,8,2);ctx.globalAlpha=1;
    if(d.t==='gold'){
      const w=Math.max(2,Math.round(6*Math.abs(Math.cos(t*5+d.ph))));
      pxRect(ctx,x-w/2-1,y-5,w+2,10,'#b8780f');pxRect(ctx,x-w/2,y-4,w,8,'#ffd54a');if(w>3)pxRect(ctx,x-w/2+1,y-3,1,3,'#fff3b0');
    }else if(d.t==='xp'){
      pxRect(ctx,x-1,y-6,2,2,'#bff6ff');pxRect(ctx,x-3,y-4,6,3,'#4fd8ff');pxRect(ctx,x-4,y-1,8,3,'#4fd8ff');
      pxRect(ctx,x-3,y+2,6,2,'#2d7fe0');pxRect(ctx,x-1,y+4,2,2,'#2d7fe0');pxRect(ctx,x-2,y-3,2,2,'#e8fdff');
    }else{
      pxRect(ctx,x-1,y-6,2,2,'#8a5a2b');pxRect(ctx,x-2,y-4,4,2,'#d8e6f0');pxRect(ctx,x-4,y-2,8,7,'#ff4f6d');
      pxRect(ctx,x-3,y,6,4,'#c42a4a');pxRect(ctx,x-3,y-1,2,2,'#ffc0cc');
    }
  }
}
const BOSS_BUFF={hp:n=>2.8+n*5.2,atk:n=>1.3+n*1.7,spd:n=>1.35+n*.4,cd:n=>.8-n*.15,cast:.92};
const MUS={calm:{bpm:84,chords:[[57,60,64],[53,57,60],[60,64,67],[55,59,62]],bass:[45,41,36,43]},
           boss:{bpm:132,chords:[[57,60,64],[57,60,64],[53,57,60],[52,56,59]],bass:[45,45,41,40]}};
const mf=m=>440*Math.pow(2,(m-69)/12);
function audMusicStep(step,t){
  const boss=AUD.mood==='boss',M=boss?MUS.boss:MUS.calm,sd=60/M.bpm/2,bar=Math.floor(step/8)%4,pos=step%8,chord=M.chords[bar],bus=AUD.mus;
  if(pos===0)chord.forEach(n=>aTone({bus,at:t,w:'sine',f:mf(n),t:sd*8,v:.05,a:.5}));
  if(boss?pos%2===0:(pos===0||pos===4))aTone({bus,at:t,w:boss?'sawtooth':'triangle',f:mf(M.bass[bar]),t:sd*1.8,v:boss?.06:.1,a:.01});
  if(boss||(pos!==1&&pos!==5)){
    const idx=[0,1,2,1,0,1,2,2][pos];
    aTone({bus,at:t,w:boss?'sawtooth':'triangle',f:mf(chord[idx]+12),t:sd*1.6,v:boss?.035:.05,a:.006});
  }
  if(boss){
    if(pos%2===0)aTone({bus,at:t,w:'sine',f:130,f2:45,t:.14,v:.25,a:.004});
    else aNoise({bus,at:t,ft:'highpass',f:7000,t:.04,v:.05});
    if(pos===2||pos===6)aNoise({bus,at:t,ft:'bandpass',f:1800,q:1,t:.1,v:.12});
  }
}
function audMusicTick(){
  try{
    const c=AUD.ctx;if(!c||c.state!=='running')return;
    const vol=Number(settings.music)||0,now=c.currentTime;
    if(now>=AUD.mixAt){
      AUD.mixAt=now+.25;
      AUD.mood=(running&&!dying&&enemies.some(e=>e.boss&&e.hp>0))?'boss':'calm';
      let g=vol*.55;if(dying)g=0;else if(paused||!running)g*=.5;
      AUD.mus.gain.setTargetAtTime(g,now,.25);
    }
    if(vol<=0){AUD.next=Math.max(AUD.next,now+.05);return;}
    if(AUD.next<now)AUD.next=now+.05;
    while(AUD.next<now+.18){audMusicStep(AUD.step++,AUD.next);AUD.next+=60/(AUD.mood==='boss'?MUS.boss.bpm:MUS.calm.bpm)/2;}
  }catch(_e){}
}



