  g.fillStyle='rgba(255,255,255,.04)';g.beginPath();g.arc(0,0,215,0,6.283);g.fill();
  g.setLineDash([14,12]);g.lineWidth=3;g.strokeStyle=theme==='snow'?'rgba(60,100,140,.3)':'rgba(255,255,255,.17)';g.beginPath();g.arc(0,0,215,0,6.283);g.stroke();
  g.setLineDash([]);g.lineWidth=2;g.strokeStyle='rgba(255,255,255,.1)';g.beginPath();g.arc(0,0,196,0,6.283);g.stroke();
