function genWorld(){
 trees=[];rocks=[];leaves=[];terrainBits=[];landmarks=[];stageHazards=[];stageWaterIsland=null;stageRiver=false;
 const st=STAGES[stageIndex],theme=st.theme,p=WORLD_PALETTES[theme],name=st.mapName.toUpperCase(),scene=st.scene.toLowerCase();
 let seed=Math.imul(stageIndex+1,2654435761)>>>0;
 const next=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
 const rr=(a,b)=>a+next()*(b-a);
 const W=WORLD.w,H=WORLD.h;
 const settlement=/village|camp|outpost|fortress|hideout|castle|city|keep|palace|post|tower|temple|gate|ruins|sanctum|throne/.test(scene);
 const lay=(stageIndex*7+2)%PATH_LAYOUTS.length;
 stagePath=PATH_LAYOUTS[lay].map(pts=>catmull(pts,14));
 stagePathW=(settlement||/pass|dunes|sand/.test(scene))?78:58;
 const corr=stagePathW/2+10;
 const isWater=theme==='water';
 stageRiver=isWater&&/RIVER|SWAMP/.test(name);
 if(isWater&&!stageRiver)stageWaterIsland={cx:800,cy:600,rx:540,ry:390,ph:rr(0,6.28)};
 const hazN=theme==='lava'?4:theme==='snow'?3:/SWAMP/.test(name)?4:0;
 for(let i=0,tries=0;i<hazN&&tries<300;tries++){
  const r=rr(70,120),x=rr(r+90,W-r-90),y=rr(r+170,H-r-90);
  if(Math.hypot(x-800,y-600)<340+r)continue;
  if(distToPath(x,y)<corr+r*1.25+20)continue;
  if(stageRiver&&Math.abs(y-riverY(x))<150+r)continue;
  if(stageHazards.some(h=>Math.hypot(h.x-x,h.y-y)<h.r+r+60))continue;
  stageHazards.push({x,y,r,ph:rr(0,6.28)});i++;
 }
 const SAFE=190,placed=[];
 const inIsland=(x,y,k)=>{const q=stageWaterIsland;if(!q)return true;const dx=(x-q.cx)/q.rx,dy=(y-q.cy)/q.ry;return dx*dx+dy*dy<k*k;};
 const free=(x,y,r,pad,k)=>{
  if(x<r||x>W-r||y<r||y>H-r*.5)return false;
  if(theme==='sky'&&(x<125||x>W-125||y<215||y>H-125))return false;
  if(Math.hypot(x-800,y-600)<SAFE+r)return false;
  if(distToPath(x,y)<corr+r*.7+(pad||0))return false;
  if(stageRiver&&Math.abs(y-riverY(x))<140+r)return false;
  if(!inIsland(x,y,k||.82))return false;
  for(const h of stageHazards)if(Math.hypot(x-h.x,y-h.y)<h.r*1.25+r)return false;
  for(const q of placed)if(Math.hypot(x-q.x,y-q.y)<q.r+r)return false;
  return true;
 };
 const lmCount=settlement?3:1+(stageIndex%2);
 for(let i=0,tries=0;i<lmCount&&tries<400;tries++){
  const s=(i===0?.95:.72)+next()*.28,r=100*s,top=next()<.72;
  const x=rr(230,W-230),y=top?rr(310,470):rr(940,1070);
  if(!free(x,y,r,24,.72))continue;
  landmarks.push({x,y,s,type:st.scene,theme,palette:p});placed.push({x,y,r:r*1.05});i++;
 }
 if(!landmarks.length)landmarks.push({x:distToPath(300,380)>140?300:1300,y:380,s:.9,type:st.scene,theme,palette:p});
 landmarks.sort((a,b)=>a.y-b.y);
 const baseTreeCount={forest:40,meadow:24,ruins:12,rocky:9,shadow:24,mushroom:22,water:0,snow:15,lava:8,desert:6,bamboo:38,sky:8,tech:4}[theme]||16;
 const treeCount=stageWaterIsland?0:baseTreeCount+(/forest|grove|wood|tree|bamboo|meadow|path/.test(scene)?14:0);
 for(let i=0,tries=0;i<treeCount&&tries<treeCount*45;tries++){
  const sc=.72+next()*.62;let x,y;
  if(next()<.42){
   const side=Math.floor(next()*4);
   if(side===0){x=rr(30,W-30);y=rr(150,250);}else if(side===1){x=rr(30,W-30);y=rr(1060,1170);}
   else if(side===2){x=rr(30,150);y=rr(200,1150);}else{x=rr(W-150,W-30);y=rr(200,1150);}
  }else{
   x=rr(70,W-70);y=rr(200,H-90);
   const d=Math.hypot((x-800)/800,(y-600)/600);
   if(next()>clamp((d-.35)/.5,.1,1))continue;
  }
  if(!free(x,y,30*sc,10,.92))continue;
  trees.push({x,y,scale:sc,sway:next()*100,theme,palette:p});placed.push({x,y,r:26*sc});i++;
 }
 const rockCount={forest:16,meadow:12,ruins:30,rocky:34,shadow:18,mushroom:14,water:11,snow:25,lava:27,desert:22,bamboo:13,sky:12,tech:23}[theme]||16;
 for(let c=0,tries=0;c<Math.ceil(rockCount/3)&&tries<300;tries++){
  const ax=rr(60,W-60),ay=rr(170,H-70);
  if(!free(ax,ay,22,8,.86))continue;
  const n=2+Math.floor(next()*3);
  for(let k=0;k<n;k++){
   const s=7+next()*12,x=ax+rr(-38,38),y=ay+rr(-26,26);
   if(!free(x,y,s*1.1,2,.9))continue;
   rocks.push({x,y,s,theme,palette:p});placed.push({x,y,r:s*1.1});
  }
  c++;
 }
 const detailTypes={forest:['grass','flower','grass'],meadow:['grass','flower','flower'],ruins:['rubble','grass'],rocky:['rubble','crystal'],shadow:['grass','rubble'],mushroom:['mushroom','flower'],water:['coral','reed'],snow:['crystal','snow'],lava:['ember','rubble'],desert:['cactus','rubble'],bamboo:['grass','reed'],sky:['cloud','crystal'],tech:['crystal','rubble']};
 const types=detailTypes[theme]||['grass'];
 const detailCount=theme==='forest'||theme==='meadow'||theme==='bamboo'||theme==='mushroom'?260:190;
 for(let i=0,tries=0;i<detailCount&&tries<detailCount*4;tries++){
  const x=rr(24,W-24),y=rr(95,H-30);
  if(distToPath(x,y)<corr+4)continue;
  if(stageRiver&&Math.abs(y-riverY(x))<130)continue;
  if(stageWaterIsland&&inIsland(x,y,1.0))continue;
  if(theme==='sky'&&(x<130||x>W-130||y<220||y>H-130))continue;
  if(stageHazards.some(h=>Math.hypot(x-h.x,y-h.y)<h.r*1.3))continue;
  const type=types[Math.floor(next()*types.length)];
  terrainBits.push({x,y,type,s:2+Math.floor(next()*2),color:theme==='mushroom'?(i%2?'#ed5da8':'#fa9857'):theme==='lava'?'#ff6428':theme==='snow'?'#b8eaff':theme==='water'?(i%2?'#ff6caa':'#44ded0'):theme==='desert'?'#82a14c':st.d,light:theme==='snow'?'#ffffff':theme==='water'?'#a1ffff':p.stone,dark:p.shade});
  i++;
 }
 const leafThemes=['forest','meadow','shadow','mushroom','bamboo'];
 if(leafThemes.includes(theme)){const colors=theme==='shadow'?['#66477c','#422c62']:[st.d,p.leaf];for(let i=0;i<24;i++)leaves.push({x:next()*W,y:next()*H,vx:rand(-20,-6),vy:rand(14,28),rot:rand(0,6.28),rotSpeed:rand(-2.5,2.5),size:rand(3,5.5),color:colors[i%colors.length]});}
 bakeStageBackground(st,rr);window.__naRebake=[st,rr];
}


function trimArrayToCap(list,cap){if(list.length>cap)list.splice(0,list.length-cap);}
