function burst(x,y,color,n=10,opts){const mult=settings.particles*getCosmeticScale();n=Math.round(n*mult);const spd=opts?.spd??100,life=opts?.life??[.25,.55];for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,v=rand(spd*.3,spd);if(!addParticle({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-spd*.3,life:rand(life[0],life[1]),color,size:Math.round(rand(2,5)),grav:opts?.grav??100}))break;}}
function floatText(x,y,t,color='#fff',big=false){if(typeof t==='number')t=String(Math.round(t));else if(typeof t==='string'&&/^[-+]?\d+\.\d+$/.test(t)){const _s=(t[0]==='-'||t[0]==='+')?t[0]:'';t=_s+Math.max(1,Math.round(Math.abs(parseFloat(t))));}if(!settings.showDamage&&!big)return;trimArrayToCap(floating,96);floating.push({x,y,t,color,life:1,age:0,big});}
function screenFlash(a){flash=Math.max(flash,a);}
function hitStopNow(t){hitStop=Math.max(hitStop,t);}
function addShake(a){shake=Math.max(shake,a*settings.shake);}
