let _ctxDepth=0;
function safeDraw(f){const d0=_ctxDepth;try{f();}catch(e){window.__drawErr=e;while(_ctxDepth>d0)ctx.restore();}}
const portalFx={active:false,t:0,dur:.85,done:false,px:0,py:0,sx:0,sy:0};
const MENU_SCREEN_SEL='#start.active,#charSel.active,#indexScreen.active,#settingsScreen.active,#aboutScreen.active,#win.active,#loadingScreen.active,#stageIntro.active';
function toastAllowed(){try{return !document.querySelector(MENU_SCREEN_SEL);}catch(_e){return true;}}
function deferGameplayToast(msg,delay,tries){setTimeout(()=>{if(document.querySelector('#start.active,#charSel.active'))return;if(toastAllowed()&&running)toast(msg);else if((tries|0)<30)deferGameplayToast(msg,700,(tries|0)+1);},delay);}
let _menuNoteT=0;
function menuNote(msg){const e=document.getElementById('menuToast');if(!e)return;e.textContent=msg;e.classList.add('on');clearTimeout(_menuNoteT);_menuNoteT=setTimeout(()=>e.classList.remove('on'),1800);}
function gameConfirm(title,msg,okTxt,cancelTxt,onOk){
  const m=document.getElementById('gcModal');if(!m){if(onOk)onOk();return;}
  document.getElementById('gcTitle').textContent=title;document.getElementById('gcMsg').textContent=msg;
  const ok=document.getElementById('gcOk'),cn=document.getElementById('gcCancel');ok.textContent=okTxt||'Oke';cn.textContent=cancelTxt||'Batal';
  const close=()=>{m.classList.remove('on');document.removeEventListener('keydown',key,true);ok.onclick=cn.onclick=m.onclick=null;};
  const key=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();}};
  ok.onclick=e=>{e.stopPropagation();close();if(onOk)onOk();};
  cn.onclick=e=>{e.stopPropagation();close();};
  m.onclick=e=>{if(e.target===m)close();};
  document.addEventListener('keydown',key,true);m.classList.add('on');
}
let toastQueue=[],toastBusy=false;
function toast(t){
  if(bossCutscene.active||t==null||t==='')return;
  if(!toastAllowed()){clearToastQueue();return;}
  const msg=String(t);
  // Queue kecil supaya notif tidak saling menimpa. Notif yang sama tidak ditumpuk.
  if(toastQueue[toastQueue.length-1]===msg)return;
  toastQueue.push(msg);
  if(toastQueue.length>5)toastQueue.splice(0,toastQueue.length-5);
  runToastQueue();
}
function runToastQueue(){
  if(toastBusy||bossCutscene.active)return;
  if(!toastAllowed()){clearToastQueue();return;}
  const e=document.getElementById('toast');
  if(!e||!toastQueue.length)return;
  toastBusy=true;
  const msg=toastQueue.shift();
  e.textContent=msg;
  e.style.opacity=1;
  e.style.transform='translateY(0)';
  clearTimeout(toast.t);
  toast.t=setTimeout(()=>{
    e.style.opacity=0;e.style.transform='translateY(-4px)';
    clearTimeout(toast.next);
    toast.next=setTimeout(()=>{toastBusy=false;runToastQueue();},260);
  },1550);
}
function clearToastQueue(){toastQueue.length=0;toastBusy=false;clearTimeout(toast.t);clearTimeout(toast.next);const e=document.getElementById('toast');if(e){e.style.opacity=0;e.style.transform='translateY(-4px)';}}
function showCombo(n){if(bossCutscene.active)return;const e=document.getElementById('combo');e.textContent='x'+n;e.style.opacity=1;e.style.transform='translate(-50%,-50%) scale(1.4)';setTimeout(()=>{e.style.transform='translate(-50%,-50%) scale(1)';},90);clearTimeout(showCombo.t);showCombo.t=setTimeout(()=>{e.style.opacity=0;},700);}
function hitEnemy(e,dmg,opts={}){if(!e||e.hp<=0||e.invuln>0&&!opts.ignoreInvuln)return;dmg=Number.isFinite(Number(dmg))?Math.max(0,Number(dmg)):0;if(perks.dmg)dmg*=1+perks.dmg*.12;if(perks.crit&&dmg>0&&Math.random()<perks.crit*.05){dmg*=1.75;floatText(e.x,e.y-44,'CRIT!','#ffef7a',true);sfx('crit');}sfx('hit');if(e.uniqueMark&&e.uniqueMark.until>=worldTime){dmg+=Number.isFinite(e.uniqueMark.dmg)?Math.max(0,e.uniqueMark.dmg):0;e.uniqueMark=null;floatText(e.x,e.y-40,'MARK BURST','#ff8cff',true);}e.hp=Math.max(0,(Number.isFinite(e.hp)?e.hp:0)-dmg);e.hit=.14;e.squash=1.2;floatText(e.x+rand(-6,6),e.y-26,'-'+Math.round(dmg),opts.color||'#ffd36b');burst(e.x,e.y-4,opts.fxColor||'#ffe08a',8,{spd:130});if(opts.knock){const dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy)||1;e.x+=dx/d*opts.knock*(e.boss?.25:1);e.y+=dy/d*opts.knock*(e.boss?.25:1);}if(opts.stun)e.stun=Math.max(e.stun,e.boss?opts.stun*.35:opts.stun);if(opts.slow)e.slow=Math.max(e.slow,e.boss?opts.slow*.6:opts.slow);const leech=clamp(Number.isFinite(player.lifesteal)?player.lifesteal:0,0,.2)+(perks.leech||0)*.02;if(leech>0&&dmg>0){const heal=dmg*leech;hp=Math.min(maxHp,hp+heal);floatText(player.x,player.y-30,'+'+Math.round(heal),'#a8ff8b');}}
function allyHit(dmg,e){if(!e||!e.boss)return dmg;const cap=(e.maxHp||1)*.0025;return Math.max(1,Math.round(Math.min(dmg*.3,cap)));}
function applyPlayerDamage(e,dmg,opts={}){if(!e||e.hp<=0)return false;dmg=Number.isFinite(Number(dmg))?Number(dmg):0;if(dmg<=0)return false;hitEnemy(e,dmg,opts);return true;}
function cleanupDeadEnemies(){for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];if(!Number.isFinite(e.hp))e.hp=0;if(e.hp<=0)killEnemy(i);}}

function attack(){if(!running||paused||bossCutscene.active||player.attackCd>0||dying||stageClearTimer>0)return;const c=currentChar,HX0=heroAtkProfile(c),baseCd=(c.ranged?.34:.40)*Math.max(.5,1-(perks.as||0)*.06)*HX0.cdm;player.attackCd=baseCd;player.attackAnim=Math.min(baseCd,.42);sfx(c.ranged?'shoot':'swing');const dmg=Math.round((atk+randInt(-2,3))*player.atkMult*player.buffAtkMult*HX0.dm);
if(c.ranged){const aa=c.autoAim||{range:600,cone:.55,predict:true,homing:1};const ps=560,target=findBestTarget(Math.min(aa.range,650),aa.cone);currentAimTarget=target;let angle;if(target){angle=aa.predict?predictAim(target,ps).angle:Math.atan2(target.y-player.y,target.x-player.x);player.dirX=Math.cos(angle);player.dirY=Math.sin(angle);}else angle=Math.atan2(player.dirY,player.dirX);if(fireBasic(c,angle,dmg,target,HX0)){return;}projectiles.push({x:player.x+Math.cos(angle)*20,y:player.y+Math.sin(angle)*20,vx:Math.cos(angle)*ps,vy:Math.sin(angle)*ps,dmg,life:1.3,color:c.projColor||c.color,r:5,pierce:c.id==='beastmaster',hitIds:[],pat:'arrow',style:c.projStyle,homing:target?(aa.homing||0):0,targetId:target?target._id:null});addShake(.04);return;}
const wp=c.weapon;let range=72,arc=.9,knock=6;
if(wp==='greatsword'){range=82;arc=1.2;knock=8;}else if(wp==='shieldmace'){range=66;arc=1;knock=22;}else if(wp==='spear'){range=110;arc=.4;knock=10;}else if(wp==='dualdagger'){range=56;arc=.7;knock=2;}else if(wp==='magicsword'){range=76;arc=.9;knock=8;}else if(wp==='wraps'){range=60;arc=.8;knock=4;}
let mstun=wp==='shieldmace'?.4:0,mslow=0;const MP=HX0.mel;if(MP){range=MP.range;arc=MP.arc;knock=MP.knock;mstun=MP.stun||mstun;mslow=MP.slow||0;}
const meleeTarget=findBestTarget(range+90,Math.min(Math.PI,arc+.58),{skipStunned:false,preferBoss:true});
if(meleeTarget){const mdx=meleeTarget.x-player.x,mdy=meleeTarget.y-player.y,md=Math.hypot(mdx,mdy)||1;player.dirX=mdx/md;player.dirY=mdy/md;}
addSlashArc(player.x,player.y,Math.atan2(player.dirY,player.dirX),range,arc,(MP&&MP.color)||c.color,.24);let hitAny=false;
if(meleeTarget){const md=Math.hypot(meleeTarget.x-player.x,meleeTarget.y-player.y);if(md<=range+meleeTarget.r+18){hitEnemy(meleeTarget,dmg,{knock,stun:mstun,slow:mslow});hitAny=true;}}
for(const e of enemies){if(e===meleeTarget)continue;const dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy)||1;if(d<range+e.r){const dot=(dx*player.dirX+dy*player.dirY)/d;if(dot>Math.cos(Math.min(Math.PI,arc+.15))){hitEnemy(e,dmg,{knock,stun:mstun,slow:mslow});hitAny=true;}}}
meleeExtra(MP,dmg);if(hitAny){hitStopNow(.045);addShake(.14);screenFlash(.10);comboCount++;comboTimer=1.6;if(comboCount>=3)showCombo(comboCount);burst(player.x+player.dirX*26,player.y+player.dirY*26,'#fff',6,{spd:180,life:[.15,.3]});}else addShake(.03);}
function nearestEnemies(range=240){return enemies.filter(e=>dist(player,e)<range+e.r).sort((a,b)=>dist(player,a)-dist(player,b));}
function damageArea(R,dmg,color,opts={}){for(const e of enemies)if(dist(player,e)<R+e.r)hitEnemy(e,dmg,{knock:opts.knock||0,stun:opts.stun||0,slow:opts.slow||0,color:'#fff',fxColor:color});burst(player.x,player.y,color,Math.min(48,18+R/8),{spd:220});addShake(opts.shake||.18);screenFlash(opts.flash||.12);}
function lineDamage(angle,len,width,dmg,color){for(const e of enemies){const dx=e.x-player.x,dy=e.y-player.y,proj=dx*Math.cos(angle)+dy*Math.sin(angle),side=Math.abs(-dx*Math.sin(angle)+dy*Math.cos(angle));if(proj>0&&proj<len&&side<width+e.r)hitEnemy(e,dmg,{knock:8,color:'#fff',fxColor:color});}addSlashArc(player.x,player.y,angle,len,.08,color,.35);burst(player.x+Math.cos(angle)*len*.5,player.y+Math.sin(angle)*len*.5,color,20,{spd:180});addShake(.2);}

function getSkillAimTarget(range=700,cone=Math.PI){return findBestTarget(range,Math.min(Math.PI,cone+.38),{skipStunned:false,preferBoss:true});}
function snapAimToTarget(target,amount=1){if(!target)return false;const a=Math.atan2(target.y-player.y,target.x-player.x),cur=Math.atan2(player.dirY,player.dirX);const d=angleDiff(a,cur);const na=cur+d*clamp(amount,0,1);player.dirX=Math.cos(na);player.dirY=Math.sin(na);currentAimTarget=target;return true;}
function castUniqueSkill(skill){const setTimeout=scheduleGameAction;const dmg=Math.round(atk*(skill.power||1)*player.buffAtkMult),m=skill.mech,color=skill.color||currentChar.colorLight||'#c080ff';const target=getSkillAimTarget(skill.range||700,skill.cone||Math.PI);let a=target?predictAim(target,skill.speed||600).angle:Math.atan2(player.dirY,player.dirX);if(target){snapAimToTarget(target,.9);a=target?predictAim(target,skill.speed||600).angle:a;player.dirX=Math.cos(a);player.dirY=Math.sin(a);}const _isUlt=(skill===currentChar.ult);spawnSkillBanner(skill,_isUlt?'ULTIMATE':(skill.slot||'SKILL'));vfxForSkill(skill,_isUlt);fxForSkill(skill,_isUlt);if(_isUlt){player.inv=Math.max(player.inv,.6);hitStopNow(.06);}
switch(m){case'cone':damageArea(105,dmg,color,{knock:20});lineDamage(a,145,55,dmg,color);break;case'ground':damageArea(145,dmg*1.15,color,{knock:45,stun:.7,shake:.3});break;case'execute':{const e=target;if(e){hitEnemy(e,Math.max(dmg,e.hp<e.maxHp*.45?e.hp:dmg),{knock:30,fxColor:color});}break;}case'archerTriple':{for(let i=0;i<3;i++){const aa=a+(i-1)*.10;projectiles.push({x:player.x+Math.cos(aa)*24,y:player.y+Math.sin(aa)*24,vx:Math.cos(aa)*760,vy:Math.sin(aa)*760,dmg:Math.round(dmg*1.25),life:1.45,color,r:5,pierce:true,hitIds:[],pat:'arrow',style:'arrow',homing:.7,targetId:target?target._id:null});}break;}case'archerRain':{const list=nearestEnemies(620).slice(0,6);const points=list.length?list.map(e=>({x:e.x,y:e.y})):Array.from({length:4},()=>({x:player.x+rand(-170,170),y:player.y+rand(-130,130)}));points.forEach((pt,i)=>setTimeout(()=>{for(let j=0;j<3;j++){const x=pt.x+rand(-35,35),y=pt.y+rand(-35,35);rainArrows.push({x,y,targetX:x,targetY:y,speed:760,delay:j*.09,color,damage:Math.round(dmg*1.15),r:5});}},i*110));break;}case'pierce':case'multiPierce':{const count=m==='multiPierce'?5:1;for(let i=0;i<count;i++){const aa=a+(i-(count-1)/2)*.12;projectiles.push({x:player.x+Math.cos(aa)*20,y:player.y+Math.sin(aa)*20,vx:Math.cos(aa)*700,vy:Math.sin(aa)*700,dmg,life:1.5,color,r:5,pierce:true,hitIds:[],pat:'arrow',style:currentChar.projStyle});}break;}case'beam':lineDamage(a,520,18,dmg*1.5,color);screenFlash(.18);break;case'mine':setTimeout(()=>{damageArea(105,dmg*1.5,color,{knock:50,stun:1});},650);break;case'blink':{const ox=player.x,oy=player.y;player.x=clamp(player.x+player.dirX*180,25,WORLD.w-25);player.y=clamp(player.y+player.dirY*180,75,WORLD.h-25);player.inv=.5;burst(ox,oy,color,18,{spd:220});damageArea(75,dmg*1.4,color,{knock:35});break;}case'pack':case'fairyStorm':case'demonLegion':{const n=m==='pack'?3:m==='fairyStorm'?5:4;for(let i=0;i<n;i++)allies.push({type:'spirit',x:player.x+rand(-55,55),y:player.y+rand(-55,55),hp:55+(i*10),maxHp:55+(i*10),dmg:Math.round(dmg*.55),life:10,maxLife:10,attackCd:rand(.2,1),phase:rand(0,6),color,faceX:1,bob:0});burst(player.x,player.y,color,24,{spd:190});break;}case'mark':case'alphaMark':case'weakpoint':{if(target){target.uniqueMark={dmg:dmg*1.8,until:worldTime+5,color};floatText(target.x,target.y-25,'MARK','#ff8cff',true);}break;}case'turret':{allies.push({type:'turret',x:player.x+player.dirX*55,y:player.y+player.dirY*55,hp:100,maxHp:100,dmg:Math.round(dmg*.7),life:12,maxLife:12,attackCd:.2,phase:0,color,faceX:1,bob:0});burst(player.x,player.y,color,20,{spd:150});break;}case'runeSlash':case'soulSlash':case'lineSlash':{lineDamage(a,210,48,dmg*1.7,color);for(let i=0;i<3;i++)setTimeout(()=>lineDamage(a+rand(-.2,.2),160,35,dmg*.5,color),i*110);break;}case'comboCone':{for(let i=0;i<6;i++)setTimeout(()=>{const aa=a+(i%2?.22:-.22);lineDamage(aa,130,45,dmg*.55,color);},i*85);break;}case'counter':{player.defendTimer=1.4;player.shieldReduction=.05;player.shieldReflect=2.2;player.inv=.35;burst(player.x,player.y,color,24,{spd:180});break;}case'dashImpact':case'charge':case'pierceDash':case'dragonDash':{player.dashTime=.45;player.isDashing=true;player.dashDirX=player.dirX;player.dashDirY=player.dirY;player.inv=.5;player.dashDmgMult=2.2;player.dashKnock=35;break;}case'healZone':case'grove':case'worldTree':{const heal=Math.round(maxHp*(m==='worldTree'?.65:.35));hp=Math.min(maxHp,hp+heal);floatText(player.x,player.y-30,'+'+heal,'#7dff9b',true);player.buffTimer=4;player.buffAtkMult=1.2;player.regen=2;burst(player.x,player.y,color,35,{spd:150});break;}case'freeze':case'freezeField':case'timeFreeze':{for(const e of enemies)if(dist(player,e)<(m==='timeFreeze'?320:190)){e.stun=Math.max(e.stun,m==='timeFreeze'?3:2);e.slow=4;}damageArea(150,dmg,color,{stun:.3});break;}case'fortify':case'curseShield':case'shield':{player.defendTimer=skill.duration||5;player.shieldReduction=.35;player.shieldReflect=.9;burst(player.x,player.y,color,30,{spd:190});break;}case'rage':case'transform':case'buff':case'overdrive':case'lifestealForm':case'wolfForm':case'mutation':{player.buffTimer=skill.duration||7;player.buffAtkMult=skill.buff||1.7;player.buffSpeedMult=1.35;player.lifesteal=skill.lifeSteal||.18;player.buffColor=color;burst(player.x,player.y,color,32,{spd:220,life:[.4,.9]});screenFlash(.25);break;}case'bloodSlash':case'bloodShot':{damageArea(125,dmg,color,{knock:18});hp=Math.min(maxHp,hp+Math.round(dmg*.35));break;}case'dragonSummon':{for(let i=0;i<2;i++)allies.push({type:'dragon',x:player.x+rand(-65,65),y:player.y+rand(-65,65),hp:130,maxHp:130,dmg:Math.round(dmg*.85),life:12,maxLife:12,attackCd:.25,phase:rand(0,6),color,faceX:1,bob:0});break;}case'rift':{const ox=player.x,oy=player.y;if(target){player.x=clamp(target.x-player.dirX*70,25,WORLD.w-25);player.y=clamp(target.y-player.dirY*70,75,WORLD.h-25);}else{player.x=clamp(player.x+player.dirX*220,25,WORLD.w-25);player.y=clamp(player.y+player.dirY*220,75,WORLD.h-25);}player.inv=.65;burst(ox,oy,color,20,{spd:220});damageArea(105,dmg*1.55,color,{knock:50,stun:.7});break;}case'gravity':case'blackhole':case'vortex':case'pull':{const R=m==='blackhole'?300:230;for(const e of enemies){const d=dist(player,e);if(d<R&&!e.boss){const k=(1-d/R)*.5;e.x+=(player.x-e.x)*k;e.y+=(player.y-e.y)*k;e.slow=2;}}damageArea(R,dmg*.7,color,{knock:5});break;}case'shockwave':case'shockField':{damageArea(190,dmg*1.2,color,{knock:65,stun:1,shake:.4,flash:.2});break;}case'chain':{let cur=target,used=new Set();for(let i=0;i<6&&cur;i++){used.add(cur._id);hitEnemy(cur,dmg*(1-i*.08),{stun:.5,fxColor:color});cur=enemies.find(e=>!used.has(e._id)&&dist(cur,e)<190);}burst(player.x,player.y,color,25,{spd:260});break;}case'meteor':case'astralMeteor':{const count=m==='astralMeteor'?5:3;for(let i=0;i<count;i++)meteors.push({x:target?target.x+rand(-40,40):player.x+rand(-180,180),y:target?target.y+rand(-40,40):player.y+rand(-180,180),targetX:target?target.x:player.x,targetY:target?target.y:player.y,startY:-500,currentY:-500,dmg:dmg*1.8,R:90,delay:i*.18,color,landed:false});break;}case'lightningRain':case'airRain':case'rainLine':{for(let i=0;i<14;i++){const x=player.x+rand(-240,240),y=player.y+rand(-180,180);setTimeout(()=>{for(const e of enemies)if(Math.hypot(e.x-x,e.y-y)<45)hitEnemy(e,dmg,{stun:.4,fxColor:color});burst(x,y,color,8,{spd:120});},i*70);}break;}case'blizzard':case'eclipse':case'tidal':case'epidemic':{damageArea(260,dmg,color,{slow:4,knock:20});for(const e of enemies)e.slow=Math.max(e.slow,4);break;}case'siege':{for(let i=0;i<4;i++)setTimeout(()=>damageArea(80,dmg*(1+i*.15),color,{knock:45}),i*140);break;}case'pullShot':case'hook':{if(target&&!target.boss){target.x=player.x+player.dirX*90;target.y=player.y+player.dirY*90;hitEnemy(target,dmg,{stun:.8,fxColor:color});}break;}case'bleed':case'venomShot':case'acid':case'plagueShot':case'hellShot':case'waterShot':case'vineShot':{if(target){hitEnemy(target,dmg,{slow:3,fxColor:color});target.hp-=dmg*.45;floatText(target.x,target.y-36,'DOT','#ff6688');}break;}case'trap':case'rootShot':case'coilTrap':{setTimeout(()=>{for(const e of enemies)if(dist(player,e)<180){e.stun=Math.max(e.stun,2);e.slow=4;}damageArea(120,dmg,color,{knock:25});},450);break;}case'dive':case'skyDive':{player.dashTime=.35;player.isDashing=true;player.dashDirX=player.dirX;player.dashDirY=player.dirY;player.dashDmgMult=3;player.dashKnock=55;player.inv=.5;break;}case'focus':case'predict':case'oracleBurst':{player.buffTimer=5;player.buffAtkMult=1.5;player.buffSpeedMult=1.2;if(target)target.uniqueMark={dmg:dmg*2,until:worldTime+5,color};break;}case'rapidShot':case'randomShot':case'fairyShot':case'gustShot':case'starShot':case'rockShot':{for(let i=0;i<6;i++){const aa=a+rand(-.18,.18);projectiles.push({x:player.x,y:player.y,vx:Math.cos(aa)*620,vy:Math.sin(aa)*620,dmg:dmg*.65,life:1.2,color,r:4,pierce:false,pat:'orb',style:currentChar.projStyle,homing:1.2,targetId:target?target._id:null});}break;}case'roulette':case'chaos':case'adaptive':{const pool=['nova','heal','dash','storm'];const pickM=pick(pool);if(pickM==='nova')damageArea(190,dmg,color,{knock:35});else if(pickM==='heal'){hp=Math.min(maxHp,hp+maxHp*.3);burst(player.x,player.y,'#7dff9b',25,{spd:180});}else if(pickM==='dash'){player.inv=.8;player.dashTime=.4;player.isDashing=true;player.dashDirX=player.dirX;player.dashDirY=player.dirY;}else for(let i=0;i<7;i++)setTimeout(()=>damageArea(100,dmg,color),i*80);break;}case'mirror':case'decoy':case'decoyTeleport':{const ox=player.x,oy=player.y;allies.push({type:'clone',x:ox+player.dirX*45,y:oy+player.dirY*45,hp:70,maxHp:70,dmg:dmg*.7,life:8,maxLife:8,attackCd:.3,phase:0,color,faceX:1,bob:0});if(m==='decoyTeleport'){player.x=clamp(ox-player.dirX*130,25,WORLD.w-25);player.y=clamp(oy-player.dirY*130,75,WORLD.h-25);}break;}case'healNova':{const h=Math.round(maxHp*.45);hp=Math.min(maxHp,hp+h);floatText(player.x,player.y-30,'+'+h,'#7dff9b',true);damageArea(100,dmg*.5,color);break;}case'soulHarvest':case'drain':{let h=0;for(const e of enemies)if(dist(player,e)<220){hitEnemy(e,dmg,{fxColor:color});h+=dmg*.35;}hp=Math.min(maxHp,hp+h);break;}case'link':{const es=nearestEnemies(300).slice(0,4);for(const e of es){e.uniqueMark={dmg:dmg*1.3,until:worldTime+4,color};}break;}case'scout':{player.buffTimer=6;player.buffAtkMult=1.35;player.buffSpeedMult=1.3;break;}case'constellation':{for(let i=0;i<8;i++){const aa=i*Math.PI/4;const x=player.x+Math.cos(aa)*150,y=player.y+Math.sin(aa)*150;setTimeout(()=>{for(const e of enemies)if(Math.hypot(e.x-x,e.y-y)<60)hitEnemy(e,dmg,{stun:.5,fxColor:color});burst(x,y,color,8,{spd:100});},i*90);}break;}case'domain':{player.buffTimer=8;player.buffAtkMult=1.8;player.buffSpeedMult=1.25;damageArea(240,dmg*.8,color,{slow:3});break;}case'decree':{for(const e of enemies){e.stun=Math.max(e.stun,1);e.slow=2;if(e.hp<e.maxHp*.3)e.hp=0;}break;}case'dimensionBreak':case'eternal2':{damageArea(300,dmg*1.5,color,{knock:70,stun:1.5,shake:.6,flash:.35});for(const e of enemies)e.slow=4;break;}case'shieldDash':{player.defendTimer=1.2;player.shieldReduction=.3;player.dashTime=.4;player.isDashing=true;player.dashDirX=player.dirX;player.dashDirY=player.dirY;player.dashDmgMult=1.8;player.dashKnock=30;break;}case'root':{for(const e of enemies)if(dist(player,e)<210){e.stun=Math.max(e.stun,2);e.slow=4;}damageArea(120,dmg*.8,color,{knock:15});break;}case'burst':{for(let i=0;i<3;i++)setTimeout(()=>damageArea(120+i*45,dmg*(.75+i*.25),color,{knock:20}),i*120);break;}case'executeRain':case'rain':{for(let i=0;i<10;i++){const e=target||pick(enemies);const x=e?e.x+rand(-45,45):player.x+rand(-180,180),y=e?e.y+rand(-45,45):player.y+rand(-140,140);setTimeout(()=>{for(const q of enemies)if(Math.hypot(q.x-x,q.y-y)<42)hitEnemy(q,dmg,{fxColor:color});burst(x,y,color,8,{spd:130});},i*80);}break;}case'buffStorm':{player.buffTimer=6;player.buffAtkMult=1.45;player.buffSpeedMult=1.25;for(let i=0;i<8;i++)setTimeout(()=>damageArea(90,dmg*.45,color,{slow:1}),i*120);break;}case'armorCrush':{for(const e of enemies)if(dist(player,e)<190){e.hp-=dmg*1.4*(1+(perks.dmg||0)*.12);e.atk*=.7;e.stun=Math.max(e.stun,.8);}damageArea(150,dmg*.5,color,{knock:35});break;}case'coneWind':{lineDamage(a,250,75,dmg,color);break;}case'rail':{lineDamage(a,650,10,dmg*2.4,color);screenFlash(.3);break;}case'chargeShot':{player.buffTimer=3;player.buffAtkMult=2.2;projectiles.push({x:player.x,y:player.y,vx:Math.cos(a)*1100,vy:Math.sin(a)*1100,dmg:dmg*2.5,life:1,color,r:9,pierce:true,pat:'orb',style:'rail'});break;}case'portalStep':{const ox=player.x,oy=player.y;player.x=clamp(player.x+player.dirX*240,25,WORLD.w-25);player.y=clamp(player.y+player.dirY*240,75,WORLD.h-25);player.inv=.7;burst(ox,oy,color,20,{spd:230});damageArea(90,dmg*1.5,color,{knock:45});break;}case'batCloud':{for(let i=0;i<8;i++){const aa=Math.random()*Math.PI*2;projectiles.push({x:player.x,y:player.y,vx:Math.cos(aa)*rand(180,420),vy:Math.sin(aa)*rand(180,420),dmg:dmg*.7,life:1.5,color,r:5,pierce:false,pat:'orb',style:'bat',homing:1.2,targetId:target?target._id:null});}hp=Math.min(maxHp,hp+dmg*.5);break;}case'multiShadow':{for(let i=0;i<7;i++){const aa=a+(i-3)*.16;projectiles.push({x:player.x,y:player.y,vx:Math.cos(aa)*650,vy:Math.sin(aa)*650,dmg:dmg*.75,life:1.3,color,r:4,pierce:true,pat:'orb',style:'shadow'});}break;}case'mutate':{player.buffTimer=6;player.buffAtkMult=1.8;player.buffSpeedMult=1.5;player.lifesteal=.3;damageArea(130,dmg*.8,color,{knock:25});break;}case'orbit':{for(let i=0;i<12;i++){const aa=i*Math.PI/6;const x=player.x+Math.cos(aa)*120,y=player.y+Math.sin(aa)*120;for(const e of enemies)if(Math.hypot(e.x-x,e.y-y)<35)hitEnemy(e,dmg*.8,{knock:12,fxColor:color});}break;}case'packCircle':{for(let i=0;i<8;i++){const aa=i*Math.PI/4;const x=player.x+Math.cos(aa)*170,y=player.y+Math.sin(aa)*170;for(const e of enemies)if(Math.hypot(e.x-x,e.y-y)<55)hitEnemy(e,dmg*.7,{knock:18,fxColor:color});}break;}case'poisonCloud':{for(let i=0;i<6;i++)setTimeout(()=>{for(const e of enemies)if(dist(player,e)<220)hitEnemy(e,dmg*.55,{slow:1,fxColor:color});burst(player.x+rand(-120,120),player.y+rand(-100,100),color,5,{spd:35});},i*250);break;}case'snakeQueen':{for(let i=0;i<5;i++)allies.push({type:'spirit',x:player.x+rand(-70,70),y:player.y+rand(-70,70),hp:80,maxHp:80,dmg:dmg*.8,life:12,maxLife:12,attackCd:.2,phase:rand(0,6),color,faceX:1,bob:0});damageArea(150,dmg,color,{slow:3});break;}case'soulShot':{if(target){hitEnemy(target,dmg*2,{fxColor:color});hp=Math.min(maxHp,hp+dmg*.25);}break;}case'sniper':{if(target){hitEnemy(target,dmg*3.5,{knock:45,fxColor:color});screenFlash(.35);addShake(.5);hitStopNow(.12);}break;}case'regen':{hp=Math.min(maxHp,hp+maxHp*.3);player.regen=4;player.buffTimer=6;burst(player.x,player.y,'#7dff9b',35,{spd:150});break;}case'sacrifice':{const cost=Math.min(hp-1,maxHp*.18);hp-=Math.max(0,cost);damageArea(280,dmg*2.2,color,{knock:70,stun:1,shake:.6});break;}default:damageArea(140,dmg,color,{knock:20});}}

function castSkill(skill){
  const setTimeout=scheduleGameAction;
  if(!running||dying||!skill||stageClearTimer>0)return;
  if(skill.unique){castUniqueSkill(skill);return;}
  const _isUlt=(skill===currentChar.ult);
  spawnSkillBanner(skill,_isUlt?'ULTIMATE':(skill===currentChar.sk1?'SKILL':skill===currentChar.sk2?'SKILL 2':'SKILL'));
  vfxForSkill(skill,_isUlt);fxForSkill(skill,_isUlt);
  if(_isUlt){player.inv=Math.max(player.inv,.6);hitStopNow(.06);}
  const c=currentChar,dmg=Math.round(atk*(skill.dmgMult??1)*player.buffAtkMult),t=skill.type;
  const aa=c.autoAim||{range:600,cone:Math.PI,predict:false};
  if(t==='nova'){const R=skill.R;for(const e of enemies)if(dist(player,e)<R+e.r)hitEnemy(e,dmg,{knock:skill.knock||0,stun:skill.stun||0,slow:skill.slow||0,color:'#ffd36b',fxColor:skill.color});addSlashArc(player.x,player.y,0,R,Math.PI,skill.color,.4);addShake(.32);screenFlash(.22);hitStopNow(.07);}
  else if(t==='multiNova'){let hit=0;const doHit=()=>{if(!running)return;addShake(.4);screenFlash(.3);const R=skill.R+hit*20;for(const e of enemies)if(dist(player,e)<R+e.r)hitEnemy(e,dmg,{knock:skill.knock||0,color:'#ff9080',fxColor:skill.color});hit++;if(hit<skill.hits)setTimeout(doHit,skill.gap);};doHit();}
  else if(t==='blast'){let angle;const target=findBestTarget(aa.range,aa.cone);if(target){angle=predictAim(target,480).angle;player.dirX=Math.cos(angle);player.dirY=Math.sin(angle);}else angle=Math.atan2(player.dirY,player.dirX);projectiles.push({x:player.x+Math.cos(angle)*20,y:player.y+Math.sin(angle)*20,vx:Math.cos(angle)*480,vy:Math.sin(angle)*480,dmg,life:1.2,color:skill.projColor||skill.color,r:7,pat:'orb',style:skill.projStyle||'orb',explodeR:skill.explodeR,explodeColor:skill.color,homing:target?(skill.homing||1):0,targetId:target?target._id:null});addShake(.08);}
  else if(t==='multi'){const target=findBestTarget(aa.range,.9),baseA=target?predictAim(target,520).angle:Math.atan2(player.dirY,player.dirX);if(target){player.dirX=Math.cos(baseA);player.dirY=Math.sin(baseA);}for(let i=-(skill.count-1)/2;i<=(skill.count-1)/2;i++){const a=baseA+i*skill.spread;projectiles.push({x:player.x+Math.cos(a)*20,y:player.y+Math.sin(a)*20,vx:Math.cos(a)*520,vy:Math.sin(a)*520,dmg,life:1.2,color:skill.color,r:5,pierce:false,pat:'arrow',style:c.projStyle,homing:skill.homing||0,targetId:target?target._id:null});}burst(player.x,player.y,skill.color,12,{spd:180});addShake(.12);}
  else if(t==='dash'){player.dashTime=skill.dur||.22;player.inv=skill.inv||.3;player.dashDirX=player.dirX;player.dashDirY=player.dirY;player.isDashing=true;player.dashDmgMult=skill.dmgMult||1;player.dashKnock=skill.knock||15;player.dashDistance=skill.distance||1;for(const e of enemies)e._dashHit=false;burst(player.x,player.y,skill.color,18,{spd:220,life:[.2,.4],grav:20});screenFlash(.12);addShake(.15);}
  else if(t==='backdash'){player.dashTime=.24;player.inv=skill.inv||.4;player.dashDirX=-player.dirX;player.dashDirY=-player.dirY;player.backstep=true;burst(player.x,player.y,skill.color,14,{spd:180});const target=findBestTarget(aa.range,1),baseA=target?predictAim(target,480).angle:Math.atan2(player.dirY,player.dirX);for(let i=0;i<skill.arrows;i++){const a=baseA+(i-(skill.arrows-1)/2)*.22;projectiles.push({x:player.x+Math.cos(a)*18,y:player.y+Math.sin(a)*18,vx:Math.cos(a)*480,vy:Math.sin(a)*480,dmg:Math.round(atk*skill.dmgMult),life:1.1,color:skill.color,r:4,pierce:false,pat:'arrow',style:c.projStyle,homing:skill.homing||0,targetId:target?target._id:null});}screenFlash(.08);}
  else if(t==='teleport'){const target=findBestTarget(500,Math.PI);if(target){const a=Math.atan2(target.y-player.y,target.x-player.x);player.dirX=Math.cos(a);player.dirY=Math.sin(a);}const dx=player.dirX,dy=player.dirY,fx=player.x,fy=player.y;player.x=clamp(player.x+dx*130,25,WORLD.w-25);player.y=clamp(player.y+dy*130,75,WORLD.h-25);player.inv=.4;burst(fx,fy,skill.color,20,{spd:200});burst(player.x,player.y,skill.color,20,{spd:200});for(const e of enemies)if(dist(player,e)<70+e.r)hitEnemy(e,Math.round(atk*skill.dmgMult),{color:'#ff8080',fxColor:skill.color,knock:20});screenFlash(.2);addShake(.18);}
  else if(t==='summon'){const count=skill.count||1;for(let i=0;i<count;i++){const a=(i/count)*Math.PI*2+worldTime;allies.push({type:skill.unit,x:player.x+Math.cos(a)*50,y:player.y+Math.sin(a)*50,hp:skill.hp,maxHp:skill.hp,dmg:skill.dmg,life:skill.life,maxLife:skill.life,attackCd:0,phase:rand(0,6),color:skill.color,faceX:1,bob:0});}burst(player.x,player.y,skill.color,20,{spd:180});screenFlash(.18);}
  else if(t==='drain'){const R=skill.R;let healed=0;for(const e of enemies)if(dist(player,e)<R+e.r){hitEnemy(e,dmg,{color:'#c060ff',fxColor:'#8040c0'});healed+=Math.round(dmg*.4);}if(healed>0){hp=Math.min(maxHp,hp+healed);floatText(player.x,player.y-30,'+'+healed,'#a8ff8b');}addShake(.2);screenFlash(.2);}
  else if(t==='meteor'){const sh=[...enemies].sort(()=>Math.random()-.5);for(let i=0;i<skill.count;i++){let tx,ty;if(i<sh.length){tx=sh[i].x+rand(-20,20);ty=sh[i].y+rand(-20,20);}else{tx=player.x+rand(-200,200);ty=player.y+rand(-200,200);}meteors.push({x:tx,y:ty,targetX:tx,targetY:ty,startY:ty-500,currentY:ty-500,dmg:Math.round(atk*skill.dmgMult*player.buffAtkMult),R:skill.R,delay:.4+i*.15,color:skill.color,landed:false});}}
  else if(t==='rain'){const se=[...enemies].sort((a,b)=>{const sa=(a.boss?200:0)+(a.elite?60:0)+Math.max(0,100-dist(player,a)*.1);const sb=(b.boss?200:0)+(b.elite?60:0)+Math.max(0,100-dist(player,b)*.1);return sb-sa;});for(let i=0;i<skill.count;i++){let tx,ty;if(i<se.length*2&&se.length>0){const e=se[i%se.length];tx=e.x+rand(-30,30);ty=e.y+rand(-30,30);}else{tx=player.x+rand(-skill.radius,skill.radius);ty=player.y+rand(-skill.radius,skill.radius);}rainArrows.push({x:tx+rand(-15,15),y:player.y-400-rand(0,200),targetX:tx,targetY:ty,dmg:Math.round(atk*skill.dmgMult*player.buffAtkMult),speed:700,delay:rand(0,.4),landed:false,color:skill.color});}addShake(.25);screenFlash(.2);}
  else if(t==='shield'){player.defendTimer=skill.dur;player.shieldReduction=Math.max(player.shieldReduction,skill.reduction||.6);player.shieldReflect=skill.reflect||0;burst(player.x,player.y,skill.color,22,{spd:180});screenFlash(.22);}
  else if(t==='rage'||t==='buff'){player.buffTimer=skill.dur;player.buffAtkMult=skill.atkMult||1;player.buffSpeedMult=skill.speedMult||1;player.buffColor=skill.color;if(skill.stealth)player.invisible=skill.dur;if(skill.lifesteal)player.lifesteal=skill.lifesteal;burst(player.x,player.y,skill.color,26,{spd:200,life:[.4,.8]});screenFlash(.25);}
  else if(t==='healBuff'){const heal=Math.round(maxHp*skill.heal);hp=Math.min(maxHp,hp+heal);floatText(player.x,player.y-30,'+'+heal+' HP','#7dff9b');player.buffTimer=skill.dur;player.buffAtkMult=skill.atkMult||1;player.buffSpeedMult=skill.speedMult||1;player.buffColor=skill.color;if(skill.regen)player.regen=skill.regen;burst(player.x,player.y,skill.color,30,{spd:180,life:[.5,1],grav:20});screenFlash(.3);}
  else if(t==='pull'){const R=skill.R;for(const e of enemies){const d=dist(player,e);if(d<R&&!e.boss){e.pull=.6;e.slow=Math.max(e.slow,skill.slowDur);}if(e.boss&&d<R)e.slow=Math.max(e.slow,skill.slowDur*.6);}addShake(.2);screenFlash(.18);}
  else if(t==='spiral'){let hit=0;const doHit=()=>{if(!running)return;const R=(skill.R/skill.hits)*(hit+1);for(const e of enemies)if(dist(player,e)<R+e.r&&!e._spiralHit){hitEnemy(e,Math.round(atk*skill.dmgMult*player.buffAtkMult),{knock:6,color:'#ffd36b',fxColor:skill.color});e._spiralHit=true;setTimeout(()=>e._spiralHit=false,200);}addSlashArc(player.x,player.y,Math.atan2(player.dirY,player.dirX),R,.6,skill.color,.2);hit++;if(hit<skill.hits)setTimeout(doHit,90);};doHit();addShake(.2);}
  else if(t==='combo'){let hit=0;const doHit=()=>{if(!running)return;const dirX=player.dirX,dirY=player.dirY,range=70;for(const e of enemies){const dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy)||1;if(d<range+e.r){const dot=(dx*dirX+dy*dirY)/d;if(dot>.4)hitEnemy(e,Math.round(atk*skill.dmgMult*player.buffAtkMult),{knock:4,color:'#ffe080',fxColor:skill.color});}}addSlashArc(player.x,player.y,Math.atan2(dirY,dirX),range,.5,skill.color,.15);hit++;if(hit<skill.hits)setTimeout(doHit,80);};doHit();}
}
function getSkillCooldown(skill){const cd=Number(skill&&skill.cd);return (Number.isFinite(cd)?Math.max(1,cd):1)*Math.max(.45,1-(perks.cd||0)*.08);}
function clampPlayerCombatStats(){player.atkMult=clamp(Number.isFinite(player.atkMult)?player.atkMult:1,1,1.8);player.speedMult=clamp(Number.isFinite(player.speedMult)?player.speedMult:1,1,1.5);player.buffAtkMult=clamp(Number.isFinite(player.buffAtkMult)?player.buffAtkMult:1,1,1.8);player.buffSpeedMult=clamp(Number.isFinite(player.buffSpeedMult)?player.buffSpeedMult:1,1,1.5);player.lifesteal=clamp(Number.isFinite(player.lifesteal)?player.lifesteal:0,0,.2);player.shieldReduction=clamp(Number.isFinite(player.shieldReduction)?player.shieldReduction:.5,0,.85);}
function skill1(){if(paused||bossCutscene.active||!running)return;if(player.skillCd<=0&&currentChar){player.skillCd=getSkillCooldown(currentChar.sk1);castSkill(currentChar.sk1);sfx('skill');clampPlayerCombatStats();}}

/* ===== SISTEM DASH 3 CHARGE (semua karakter) ===== */
const DODGE={max:3,rech:5};
player.dodge=DODGE.max;player.dodgeT=0;
function dodge(){
  if(paused||bossCutscene.active||!running||dying||stageClearTimer>0)return;
  if(player.dodge<=0||player.dashTime>0)return;
  player.dodge--;if(player.dodge===DODGE.max-1)player.dodgeT=0;
  let dx=player.dirX,dy=player.dirY;const l=Math.hypot(dx,dy)||1;dx/=l;dy/=l;
  player.dashTime=.2;player.inv=Math.max(player.inv,.3);
  player.dashDirX=dx;player.dashDirY=dy;player.isDashing=true;player.dashDmgMult=0;player.dashKnock=0;player.dashDistance=1;
  for(const e of enemies)e._dashHit=true;
  const col=(currentChar&&(currentChar.colorLight||currentChar.color))||'#9ff';
  try{burst(player.x,player.y,col,10,{spd:180,life:[.15,.3],grav:20});}catch(_){}
  try{if(FX_READY){const a=Math.atan2(dy,dx);
    for(let i=0;i<3;i++){const o=(i-1)*12;fx({tex:'needle',x:player.x,y:player.y,ox:-dx*18-dy*o,oy:-dy*18+dx*o,rot:a+Math.PI/2,s0:90,s1:130,sx:.35,color:i===1?'#fff':col,life:.28,core:.5,vx:dx*60,vy:dy*60,fin:.08,hold:.3});}
    fx({tex:'smoke'+((Math.random()*4)|0),x:player.x,y:player.y+8,s0:30,s1:70,color:col,life:.4,a:.6});
    fx({tex:'wind',x:player.x,y:player.y,s0:30,s1:90,color:col,life:.3,rotSp:-10,core:.3,sq:.8});}}catch(_){}
  try{sfx('dash');}catch(_){}
}
function dodgeTick(dt){
  if(player.dodge<DODGE.max){player.dodgeT+=dt;if(player.dodgeT>=DODGE.rech){player.dodge++;player.dodgeT=0;}}else player.dodgeT=0;
}
(function(){
  const btn=document.getElementById('dodgeBtn');if(!btn)return;
  btn.addEventListener('pointerdown',e=>{e.preventDefault();dodge();});
  addEventListener('keydown',e=>{if(e.repeat||bossCutscene.active)return;if(e.code==='KeyF'||e.code==='ShiftLeft'||e.code==='ShiftRight')dodge();});
  const pips=btn.querySelectorAll('.pips b'),num=btn.querySelector('.cdNum');let last='';
  (function loop(){try{
    const c=player.dodge|0,full=c>=DODGE.max,rem=Math.max(0,DODGE.rech-player.dodgeT);
    const deg=full?0:Math.round((rem/DODGE.rech)*360),txt=c===0?rem.toFixed(1):'';
    const sig=c+'|'+deg+'|'+txt;
    if(sig!==last){last=sig;pips.forEach((p,i)=>p.classList.toggle('on',i<c));btn.style.setProperty('--cd',deg+'deg');if(num)num.textContent=txt;btn.classList.toggle('empty',c===0);}
  }catch(_){}requestAnimationFrame(loop)})();
})();
function skill2(){if(paused||bossCutscene.active||!running)return;if(player.dashCd<=0&&currentChar){player.dashCd=getSkillCooldown(currentChar.sk2);castSkill(currentChar.sk2);sfx('dash');clampPlayerCombatStats();}}
function ultimate(){if(paused||bossCutscene.active||!running)return;if(player.ultCd<=0&&currentChar){player.ultCd=getSkillCooldown(currentChar.ult);castSkill(currentChar.ult);sfx('ult');clampPlayerCombatStats();}}

function getEnemySkillProfile(def,stage){const n=(def.n||'').toLowerCase(),v=(def.v||'').toLowerCase(),w=(def.w||'').toLowerCase(),p=(def.p||'').toLowerCase();const st=(stage.n||'').toLowerCase();if(/mage|sorcerer|witch|wizard|warlock/.test(n)||w==='staff')return'arcane';if(/archer|sniper|hunter|ranger/.test(n)||w==='bow')return'volley';if(/scorpion|snake|serpent|spore|toxic|poison|venom/.test(n+' '+v+' '+st))return'poison';if(/ice|frost|snow|blizzard|crystal/.test(n+' '+v+' '+st))return'frost';if(/fire|lava|magma|inferno|flame|volcano/.test(n+' '+v+' '+st))return'flame';if(/storm|thunder|tempest|lightning/.test(n+' '+v+' '+st))return'storm';if(/time|chronos/.test(n+' '+v+' '+st))return'time';if(/void|abyss|eldritch|shadow|dark/.test(n+' '+v+' '+st))return'void';if(/kraken|leviathan|whale|fish|jellyfish|sea|ocean|atlantis/.test(n+' '+v+' '+st))return'tide';if(/treant|spirit|pixie|fairy|sprite|bamboo|forest|world tree/.test(n+' '+v+' '+st))return'nature';if(/demon|hell|devil|succubus|hellhound/.test(n+' '+v+' '+st))return'hell';if(/assassin|ninja|rogue/.test(n+' '+v))return'blink';if(/golem|titan|colossus|guardian|knight|paladin/.test(n+' '+v))return'quake';if(/dragon|drake|wyrm|phoenix/.test(n+' '+v))return'dragon';if(w==='axe'||w==='club')return'smash';if(w==='spear'||w==='trident')return'pierce';if(w==='katana'||w==='dagger'||w==='sword')return'slash';if(p==='ghost'||p==='worm')return'phase';if(p==='bug'||p==='beast')return'pounce';return def.boss?'boss':'smash';}
function bossDamageCap(e,mult=1){const raw=Number(e?.atk||0)*mult;if(!(e&&e.boss))return Math.max(1,Math.round(Number.isFinite(raw)?raw:1));const base=Math.max(1,maxHp||1);const phase=(e.bossPhase|0)===2?1.12:(e.bossPhase|0)===1?1.06:1;return Math.max(1,Math.round(clamp(raw,base*.045,base*.085)*phase));}
function enemySkillDamage(e,mult=1){return bossDamageCap(e,mult);}
function enemyHitPlayer(dmg,color='#ff5069',inv=.45,shake=.14){if(player.inv>0||dying)return false;dmg=Math.max(0,Math.round(Number.isFinite(dmg)?dmg:0));hp=Math.max(0,hp-dmg);player.inv=inv;sfx('hurt');floatText(player.x+rand(-6,6),player.y-30,'-'+dmg,color);burst(player.x,player.y,color,10,{spd:150});addShake(shake);screenFlash(.08);return true;}
function enemySkillEffect(e,d,dx,dy){const setTimeout=scheduleGameAction;if(e.skillCd>0||dying)return false;const a=Math.atan2(dy,dx),c=e.c;let used=true;const cd=Math.max(1.35,e.skillBaseCd*(1-getStageDifficultyNorm(stageIndex)*0.30));
switch(e.skillType){case'arcane':if(d<110||d>520){used=false;break;}e.skillCd=cd;for(let i=-1;i<=1;i++)enemyProjectile(e,a+i*.22,enemySkillDamage(e,i===0?1.05:.58),{speed:330+stageIndex*2,style:'magic',r:i===0?8:5,life:2,explodeR:e.elite?30:0,color:c});break;
case'volley':if(d<150||d>560){used=false;break;}e.skillCd=cd;for(let i=-2;i<=2;i++)enemyProjectile(e,a+i*.10,enemySkillDamage(e,i===0?1:.48),{speed:500,style:'arrow',pat:'arrow',r:4,life:1.6,color:c});break;
case'poison':if(d>360){used=false;break;}e.skillCd=cd+1;enemyProjectile(e,a,enemySkillDamage(e,.72),{speed:260,style:'poison',r:8,life:2.4,explodeR:32,color:'#7dff5b',explodeColor:'#7dff5b',status:{type:'poison',dur:4,dps:enemySkillDamage(e,.12)}});break;
case'frost':if(d>360){used=false;break;}e.skillCd=cd+1.2;enemyProjectile(e,a,enemySkillDamage(e,.65),{speed:250,style:'ice',r:10,life:2.2,explodeR:42,color:'#9ee8ff',explodeColor:'#9ee8ff',status:{type:'freeze',dur:1.8,dps:0}});break;
case'flame':if(d>320){used=false;break;}e.skillCd=cd;for(let i=-2;i<=2;i++)enemyProjectile(e,a+i*.12,enemySkillDamage(e,.55),{speed:360,style:'fire',r:6,life:1.7,explodeR:22,color:'#ff632f',explodeColor:'#ff9b3d',status:{type:'burn',dur:3,dps:enemySkillDamage(e,.1)}});break;
case'storm':if(d>430){used=false;break;}e.skillCd=cd+1;const sx=player.x+rand(-70,70),sy=player.y+rand(-70,70);setTimeout(()=>{if(!running||dying)return;if(Math.hypot(player.x-sx,player.y-sy)<48){enemyHitPlayer(enemySkillDamage(e,.95),'#fff080',.55,.22);applyStatus('shock',2.5,enemySkillDamage(e,.15));}burst(sx,sy,'#fff080',20,{spd:220});},420);break;
case'void':if(d>390){used=false;break;}e.skillCd=cd;for(let i=0;i<6;i++)enemyProjectile(e,a+i*Math.PI/3,enemySkillDamage(e,.48),{speed:280,style:'orb',r:7,life:2.1,color:'#a060ff',explodeR:18});break;
case'tide':if(d>330){used=false;break;}e.skillCd=cd+1;enemyProjectile(e,a,enemySkillDamage(e,.75),{speed:300,style:'water',r:11,life:2.2,explodeR:48,color:'#4fdcff'});break;
case'nature':if(d>300){used=false;break;}e.skillCd=cd+1;enemyProjectile(e,a,enemySkillDamage(e,.65),{speed:220,style:'root',r:8,life:2.4,explodeR:38,color:'#72e36b'});break;
case'hell':if(d>360){used=false;break;}e.skillCd=cd;enemyProjectile(e,a,enemySkillDamage(e,.9),{speed:390,style:'fire',r:7,life:1.8,explodeR:28,color:'#ff3b61'});break;
case'blink':if(d>300||d<70){used=false;break;}e.skillCd=cd+1;const ox=e.x,oy=e.y;e.x=clamp(player.x-dx/d*75,30,WORLD.w-30);e.y=clamp(player.y-dy/d*75,80,WORLD.h-30);burst(ox,oy,c,12,{spd:170});burst(e.x,e.y,c,16,{spd:180});enemyHitPlayer(enemySkillDamage(e,1.25),'#ff4d83',.6,.28);break;
case'quake':if(d>180){used=false;break;}e.skillCd=cd;burst(e.x,e.y,c,24,{spd:230});if(d<155)enemyHitPlayer(enemySkillDamage(e,1.4),'#ff704d',.65,.3);break;
case'dragon':if(d>500){used=false;break;}e.skillCd=cd;for(let i=-2;i<=2;i++)enemyProjectile(e,a+i*.11,enemySkillDamage(e,.72),{speed:360,style:'fire',r:7,life:2,explodeR:26,color:c});break;
case'pierce':if(d<90||d>330){used=false;break;}e.skillCd=cd;e.charging=.32;e.vx=dx/d*(470+stageIndex*2);e.vy=dy/d*(470+stageIndex*2);break;
case'slash':if(d>120){used=false;break;}e.skillCd=cd;if(d<110)enemyHitPlayer(enemySkillDamage(e,1.2),'#ff8060',.5,.2);break;
case'phase':if(d>330){used=false;break;}e.skillCd=cd+1;const px=e.x,py=e.y;e.x=clamp(player.x+rand(-150,150),30,WORLD.w-30);e.y=clamp(player.y+rand(-120,120),80,WORLD.h-30);burst(px,py,c,10,{spd:130});burst(e.x,e.y,c,16,{spd:160});break;
case'pounce':if(d>260){used=false;break;}e.skillCd=cd;e.charging=.30;e.vx=dx/d*(410+stageIndex*2);e.vy=dy/d*(410+stageIndex*2);break;
case'smash':if(d>155){used=false;break;}e.skillCd=cd;if(d<125)enemyHitPlayer(enemySkillDamage(e,1.35),'#ff704d',.6,.28);break;
case'boss':if(d>620){used=false;break;}e.skillCd=Math.max(2.1,cd*.8);for(let i=0;i<12;i++)enemyProjectile(e,a+i*Math.PI/6,enemySkillDamage(e,.55),{speed:260+stageIndex,style:'orb',r:7,life:2.5,color:c,explodeR:18});if(d<180)enemyHitPlayer(enemySkillDamage(e,1.25),'#ff3b6b',.6,.35);break;
default:used=false;}if(used)e.skillFlash=.28;return used;}
function getSurvivalDuration(idx){
  // 55s awal, bertambah perlahan hingga 120s di stage 100.
  if(idx>=STAGES.length-1)return 150;
  return Math.round(Math.min(120,55+idx*0.66));
}
function updateSurvivalHud(){
  const el=document.getElementById('survivalHud'),timer=document.getElementById('survivalTimer'),fill=document.getElementById('survivalFill'),label=document.getElementById('survivalLabel');
  if(!el||!timer)return;
  const remain=Math.max(0,survivalRemaining),m=Math.floor(remain/60),sec=Math.floor(remain%60);
  timer.textContent=String(m).padStart(2,'0')+':'+String(sec).padStart(2,'0');
  const pct=survivalDurationCurrent>0?Math.max(0,Math.min(100,remain/survivalDurationCurrent*100)):0;
  if(fill)fill.style.width=pct+'%';
  el.classList.toggle('urgent',remain<=10&&!survivalExpired);
  if(label)label.textContent=survivalExpired?(portal?'🚪':'⚔️'):'⏳';
}
function getStageSpawnConfig(){const stageIdx=stageIndex,s=stageIdx+1,isFinal=stageIdx>=STAGES.length-1,tier=getDifficultyTier(stageIdx),norm=getStageDifficultyNorm(stageIdx);const targetKills=15;const cap=Math.min(8,3+Math.floor(norm*5));const initial=isFinal?1:Math.min(cap,2+Math.floor(norm*2));const interval=Math.max(0.7,1.8-norm*1.1);return{cap,initial,interval,targetKills,tier,diff:getStageDifficulty(stageIdx),st:STAGES[stageIdx]};}

function getBossIntroQuote(boss){
  const world=STAGES[boss.si]?.mapName||'dunia ini';
  const identity=boss.name.toUpperCase();
  const kind=(boss.p+' '+boss.v+' '+boss.name).toLowerCase();
  if(/dragon|naga/.test(kind))return `Akulah ${identity}, naga yang menjaga ${world}. Satu tarikan napasku cukup untuk mengubah harapanmu menjadi abu.`;
  if(/demon|imp|devil/.test(kind))return `Aku ${identity}, penguasa kegelapan ${world}. Serahkan nyalimu—atau biar kutarik sendiri dari dadamu.`;
  if(/king|queen|ruler|emperor|royal/.test(kind))return `Berlututlah. Aku ${identity}, penguasa sah ${world}. Tak ada pahlawan yang pulang membawa mahkotaku.`;
  if(/golem|titan|colossus/.test(kind))return `Namaku ${identity}. Selama batu-batu ${world} masih berdiri, tak seorang pun akan melewatiku.`;
  if(/ghost|spirit|wraith|phantom|lich|undead|reaper/.test(kind))return `Aku ${identity}, gema terakhir dari ${world}. Sebentar lagi namamu menjadi bisikan berikutnya.`;
  if(/beast|wolf|bear|wyvern/.test(kind))return `${identity} mencium ketakutanmu. Ini wilayahku—dan perburuan di ${world} berakhir di sini.`;
  if(/robot|mech|android|machine/.test(kind))return `${identity}: protokol penjaga ${world} aktif. Ancaman terdeteksi. Pemusnahan dimulai sekarang.`;
  return `Aku ${identity}, penjaga terakhir ${world}. Buktikan bahwa langkahmu lebih kuat daripada seluruh kegelapan di dunia ini.`;
}
