function buildBossDialogue(def,idx,mapName,ch){
  const m=mapName||'wilayah ini',n=def.n;const f=s=>s.replace(/\{n\}/g,n).replace(/\{m\}/g,m);
  const A=BOSS_ARCH[def.p]||BOSS_ARCH.humanoid,S=BOSS_SPECIAL[idx],tier=idx<15?0:idx<40?1:idx<70?2:idx<90?3:4;
  const hero=(ch&&ch.name)||'HERO',icon=(ch&&ch.icon)||'🛡️',col=(ch&&ch.color)||'#2a6a88';
  const opening=f(S?S[0]:A[0]);const threat=f(S?S[1]:(BOSS_ELEM[def.bp]||A[1]));
  const reply=BOSS_HERO[tier];
  const twist=tier>=3?'Kau bukan sekadar penjaga dunia ini. Kau adalah penghalang terakhir sebelum Rift terbuka.':BOSS_CLOSE[tier][idx%2];
  return [
    {who:'boss',t:opening},
    {who:'boss',t:threat},
    {who:'hero',name:hero,icon,col,t:reply},
    {who:'boss',t:twist},
    ...(bossMemLine()?[{who:'boss',t:bossMemLine()}]:[]),
    {who:'hero',name:hero,icon,col,t:'Kalau ini akhir jalanku... aku akan menulis akhirnya dengan tanganku sendiri.'}
  ];
}
/*CINE_DATA_END*/
function cineEase(x){x=clamp(x,0,1);return x*x*(3-2*x);}
function cinePart(x,y,col,n,spd,life,up){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,v=spd*(.3+Math.random());bossCutscene.parts.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v*(up?.5:1)-(up?spd*.45:0),life:life*(.6+Math.random()*.6),max:life,col,sz:2+Math.random()*3,g:up?90:0});}}
function cineSetState(s){const c=bossCutscene;c.state=s;c.pt=0;if(s==='talk'){c.li=0;c.chars=0;c.hold=0;c.guard=.5;}if(s==='out')c.intro=1;}
function cineNext(){const c=bossCutscene;c.li++;if(c.li>=c.lines.length){cineSetState('out');return;}c.chars=0;c.hold=0;c.guard=.3;}
function cineAdvance(){const c=bossCutscene;if(!c.active||c.state!=='talk'||c.guard>0)return;const L=c.lines[c.li];if(c.chars<L.t.length){c.chars=L.t.length;c.hold=0;c.guard=.15;}else cineNext();}
function cineSkip(){const c=bossCutscene;if(!c.active||c.state==='out'||c.t<1)return;c.intro=1;cineSetState('out');}
function clearEnemyThreats(){for(let i=projectiles.length-1;i>=0;i--)if(projectiles[i].fromEnemy)projectiles.splice(i,1);warningZones.length=0;keys.w=keys.a=keys.s=keys.d=keys.ArrowUp=keys.ArrowDown=keys.ArrowLeft=keys.ArrowRight=false;joy.x=joy.y=0;joy.active=false;}
function finishBossCutscene(){
  const c=bossCutscene,b=c.boss;
  document.body.classList.remove('cutscene');c.active=false;c.state='';c.endedAt=performance.now();c.boss=null;cameraZoom=1;
  const tx=player.x+player.dirX*55-W/2,ty=player.y+player.dirY*55-H/2;
  camX=(W>=WORLD.w)?(WORLD.w-W)/2:clamp(tx,0,WORLD.w-W);
  camY=(H>=WORLD.h)?(WORLD.h-H)/2:clamp(ty,0,WORLD.h-H);
  if(b){b.introTimer=0;b.invuln=.8;b.globalCd=1.6;b.attackCd=1.0;b.castTimer=0;}
  player.inv=Math.max(player.inv,1.2);
  clearEnemyThreats();
  document.getElementById('game').classList.remove('cine');
  spawnBossBanner(c.name,'⚔️ PERTARUNGAN DIMULAI',c.color,'⚔️');
  flash=Math.max(flash,.3);
}
function startBossCutscene(def,e){sfx('boss');
  SKILL_BANNER.life=0;BOSS_BANNER.life=0;
  clearToastQueue();const _toast=document.getElementById('toast'),_combo=document.getElementById('combo');if(_toast)_toast.style.opacity=0;if(_combo)_combo.style.opacity=0;
  const c=bossCutscene,idx=stageIndex|0;
  document.body.classList.add('cutscene');c.active=true;c.t=0;c.pt=0;c.state='in';c.boss=e;c.intro=0;c.impact=false;c.parts=[];c.skipRect=null;
  c.name=(def.n||'BOSS').toUpperCase();c.map=((STAGES[idx]&&STAGES[idx].mapName)||'').toUpperCase();c.stage=idx+1;
  c.color=/^#[0-9a-f]{6}$/i.test(def.c||'')?def.c:'#ff3050';
  c.lines=buildBossDialogue(def,idx,STAGES[idx]&&STAGES[idx].mapName,currentChar);c.li=0;c.chars=0;c.hold=0;c.guard=0;
  // posisikan boss di depan hero supaya selalu terlihat jelas saat muncul
  let dx=WORLD.w/2-player.x,dy=WORLD.h/2-player.y,d=Math.hypot(dx,dy);
  if(d<80){dx=player.dirX||1;dy=player.dirY||0;d=Math.hypot(dx,dy)||1;}
  e.x=clamp(player.x+dx/d*300,60,WORLD.w-60);e.y=clamp(player.y+dy/d*300,110,WORLD.h-60);
  if(Math.hypot(e.x-player.x,e.y-player.y)<200){e.x=clamp(player.x-dx/d*300,60,WORLD.w-60);e.y=clamp(player.y-dy/d*300,110,WORLD.h-60);}
  e.invuln=999;e.introTimer=999;
  clearEnemyThreats();
  document.getElementById('game').classList.add('cine');
}
function updateBossCutscene(dt){
  const c=bossCutscene,b=c.boss;
  if(!b||b.hp<=0||b._dead){finishBossCutscene();return;}
  c.t+=dt;c.pt+=dt;
  for(let i=c.parts.length-1;i>=0;i--){const p=c.parts[i];p.life-=dt;if(p.life<=0){c.parts.splice(i,1);continue;}p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=p.g*dt;p.vx*=.985;}
  if(c.state==='in'){
    c.intro=cineEase((c.t-1.55)/1.05);
    if(c.t>.9&&c.t<CINE.IMPACT){shake=Math.max(shake,.07+.1*(c.t/CINE.IMPACT));if(Math.random()<.5)cinePart(b.x+rand(-b.r,b.r)*1.5,b.y+b.r*.8,c.color,1,90,.9,true);}
    if(!c.impact&&c.t>=CINE.IMPACT){c.impact=true;shake=Math.max(shake,1);flash=Math.max(flash,.75);cinePart(b.x,b.y+b.r*.8,c.color,70,420,1.1,true);cinePart(b.x,b.y+b.r*.8,'#ffffff',30,300,.8,true);}
    if(c.t>=CINE.IN)cineSetState('title');
  }else if(c.state==='title'){c.intro=1;if(c.pt>=CINE.TITLE)cineSetState('talk');}
  else if(c.state==='talk'){
    const L=c.lines[c.li];c.guard=Math.max(0,c.guard-dt);c.chars=Math.min(L.t.length,c.chars+dt*40);
    if(c.chars>=L.t.length){c.hold+=dt;if(c.hold>1.7+L.t.length*.012)cineNext();}
  }else if(c.state==='out'){if(c.pt>=CINE.OUT){finishBossCutscene();return;}}
  cineCamera();
}
function cineCamera(){
  const c=bossCutscene,b=c.boss;if(!b)return false;
  const P={x:player.x+player.dirX*55,y:player.y+player.dirY*55};
  let fx=P.x,fy=P.y,z=1,yo=0;
  if(c.state==='in'){const k=cineEase((c.t-.5)/1.6);fx=P.x+(b.x-P.x)*k;fy=P.y+(b.y-P.y)*k;z=1+.1*k;}
  else if(c.state==='title'){const k=cineEase(c.pt/1.0);fx=b.x;fy=b.y;z=1.1+.38*k;yo=.14*k;}
  else if(c.state==='talk'){fx=b.x;fy=b.y;z=1.48+.025*Math.sin(c.pt*.6);yo=.14;}
  else{const k=cineEase(c.pt/CINE.OUT);fx=b.x+(P.x-b.x)*k;fy=b.y+(P.y-b.y)*k;z=1.48-.48*k;yo=.14*(1-k);}
  cameraZoom=z;const vw=W/z,vh=H/z;
  let cx=fx,cy=fy+yo*vh;
  cx=vw>=WORLD.w?WORLD.w/2:clamp(cx,vw/2,WORLD.w-vw/2);
  cy=vh>=WORLD.h?WORLD.h/2:clamp(cy,vh/2,WORLD.h-vh/2);
  camX=cx-W/2;camY=cy-H/2;return true;
}
function drawEnemy(e){
  const c=bossCutscene;
  if(e.boss&&c.active&&c.boss===e){
    const k=c.intro;if(k<=0)return;
    const rise=(1-k)*(1-k)*70,sc=.55+.45*k;
    ctx.save();ctx.globalAlpha=Math.min(1,k*1.6);ctx.translate(e.x,e.y+rise);ctx.scale(sc,sc);ctx.translate(-e.x,-e.y);_drawEnemyOrig(e);ctx.restore();
    if(k<1){ctx.save();ctx.globalAlpha=(1-k)*.6;ctx.globalCompositeOperation='lighter';ctx.translate(e.x,e.y+rise);ctx.scale(sc,sc);ctx.translate(-e.x,-e.y);_drawEnemyOrig(e);ctx.restore();}
    return;
  }
  _drawEnemyOrig(e);
}
function drawBossSummonWorld(){
  const c=bossCutscene,b=c.boss;if(!c.active||!b)return;
  const col=c.color,t=c.t,R=Math.max(95,b.r*3.1),fo=c.state==='out'?1-clamp(c.pt/CINE.OUT,0,1):1;
  const a=clamp((t-.35)/.8,0,1)*fo,gy=b.y+b.r*.85;
  ctx.save();ctx.globalCompositeOperation='lighter';
  if(a>0){
    ctx.save();ctx.translate(b.x,gy);ctx.scale(1,.4);
    const g=ctx.createRadialGradient(0,0,R*.05,0,0,R*1.1);g.addColorStop(0,col);g.addColorStop(1,col+'00');
    ctx.globalAlpha=.42*a;ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,R*1.1,0,7);ctx.fill();
    ctx.globalAlpha=.9*a;ctx.strokeStyle=col;ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,R,0,7);ctx.stroke();
    ctx.lineWidth=2;ctx.strokeStyle='#ffd45e';ctx.beginPath();ctx.arc(0,0,R*.82,0,7);ctx.stroke();
    ctx.setLineDash([10,14]);ctx.lineDashOffset=-t*40;ctx.strokeStyle='#fff';ctx.globalAlpha=.55*a;ctx.beginPath();ctx.arc(0,0,R*.66,0,7);ctx.stroke();ctx.setLineDash([]);
    ctx.rotate(t*.5);ctx.strokeStyle=col;ctx.globalAlpha=.8*a;ctx.lineWidth=2;
    for(let k=0;k<2;k++){ctx.beginPath();for(let i=0;i<3;i++){const an=i*Math.PI*2/3+k*Math.PI/3,x=Math.cos(an)*R*.78,y=Math.sin(an)*R*.78;i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.closePath();ctx.stroke();}
    ctx.fillStyle='#ffd45e';for(let i=0;i<12;i++){const an=i*Math.PI/6;ctx.fillRect(Math.cos(an)*R*.9-3,Math.sin(an)*R*.9-3,6,6);}
    ctx.restore();
  }
  if(t>1.0){
    const pa=clamp((t-1.0)/.6,0,1)*(t<CINE.IMPACT+.5?1:clamp(1-(t-CINE.IMPACT-.5)/.8,0,1))*fo;
    if(pa>0){const pw=R*.55*(1+.05*Math.sin(t*14)),top=gy-420;
      const lg=ctx.createLinearGradient(b.x-pw,0,b.x+pw,0);lg.addColorStop(0,col+'00');lg.addColorStop(.5,'#ffffff');lg.addColorStop(1,col+'00');
      ctx.globalAlpha=.55*pa;ctx.fillStyle=lg;ctx.fillRect(b.x-pw,top,pw*2,gy-top);
      const vg=ctx.createLinearGradient(0,top,0,gy);vg.addColorStop(0,col+'00');vg.addColorStop(1,col);
      ctx.globalAlpha=.35*pa;ctx.fillStyle=vg;ctx.fillRect(b.x-pw*1.6,top,pw*3.2,gy-top);}
  }
  if(t>CINE.IMPACT){for(let i=0;i<3;i++){const k=t-CINE.IMPACT-i*.18;if(k<0||k>1.1)continue;ctx.save();ctx.translate(b.x,gy);ctx.scale(1,.4);ctx.globalAlpha=(1-k/1.1)*.85*fo;ctx.strokeStyle=i?col:'#fff';ctx.lineWidth=8*(1-k/1.1)+1;ctx.beginPath();ctx.arc(0,0,40+k*R*2.4,0,7);ctx.stroke();ctx.restore();}}
  for(const p of c.parts){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.col;const s=p.sz;ctx.fillRect(Math.round(p.x-s/2),Math.round(p.y-s/2),s,s);}
  ctx.restore();
}

function beginBossCutscene(boss){
  if(!boss||bossCutscene.active)return;
  const def=(typeof ET!=='undefined'&&ET[boss.et])||{n:boss.name,p:boss.p,c:boss.c,bp:''};
  startBossCutscene(def,boss);
}
function advanceBossCutscene(){cineAdvance();}
function tickBossCutscene(dt){updateBossCutscene(dt);}

function spawnEnemy(forceBoss=false,spawnOpts=null){const st=STAGES[stageIndex];let idx;const normalPool=st.pool||[];const spawnCfg=getStageSpawnConfig();const progress=spawnCfg.targetKills>0?killsInStage/spawnCfg.targetKills:0;let unlocked=normalPool.length;if(progress<.34)unlocked=Math.min(1,normalPool.length);else if(progress<.70)unlocked=Math.min(2,normalPool.length);const activePool=normalPool.slice(0,unlocked);if(spawnOpts&&spawnOpts.summoned)idx=normalPool.length?normalPool[0][0]:st.boss;else if(normalPool.length===0)idx=st.boss;else if(forceBoss&&st.boss!==undefined&&!enemies.some(e=>e.boss))idx=st.boss;else if(st.boss!==undefined&&!enemies.some(e=>e.boss)&&killsInStage>=spawnCfg.targetKills)idx=st.boss;else{const pool=activePool.length?activePool:normalPool.slice(0,1);idx=weightedPick(pool.map(p=>p[0]),pool.map(p=>p[1]));}
const def=ET[idx];if(!def)return;let x,y,tries=0;if(spawnOpts&&Number.isFinite(spawnOpts.overrideX)){x=spawnOpts.overrideX;y=spawnOpts.overrideY;}else do{x=rand(60,WORLD.w-60);y=rand(100,WORLD.h-60);tries++;}while(Math.hypot(x-player.x,y-player.y)<220&&tries<40);
const diffNorm=getStageDifficultyNorm(stageIndex);const eliteChance=Math.min(.27,st.elite+diffNorm*.07);const isElite=!def.boss&&Math.random()<eliteChance;const hpM=isElite?1.55:1,eliteAtkM=isElite?1.22:1,sM=clamp(Number.isFinite(settings.difficulty)?settings.difficulty:1,.75,1.35);const hpScale=(1+diffNorm*1.5)*(def.boss?BOSS_BUFF.hp(diffNorm):1),atkScale=def.boss?(1+diffNorm*.55)*BOSS_BUFF.atk(diffNorm):1+diffNorm*1.3,spdScale=def.boss?(1+diffNorm*.05)*BOSS_BUFF.spd(diffNorm):1+diffNorm*.28;const role=def.w==='bow'?'ranged':def.w==='staff'?'mage':def.w==='spear'?'lancer':def.w==='axe'?'bruiser':(def.w==='dagger'||def.w==='katana')?'assassin':def.boss?'boss':(def.ai==='pounce'?'charger':'melee');const skillType=def.sp||getEnemySkillProfile(def,st);const skillBaseCd=Math.max(2.0,4.2-stageIndex*.012)+(isElite?-.5:0);
const enemyHp=Math.max(1,Number.isFinite(def.hp*hpM*sM*hpScale)?def.hp*hpM*sM*hpScale:1),enemyAtk=Math.max(0,Number.isFinite(def.atk*sM*atkScale*eliteAtkM)?def.atk*sM*atkScale*eliteAtkM:0),enemySpd=Math.max(0,Number.isFinite(def.spd*spdScale)?def.spd*spdScale:0),rewardScale=(1+diffNorm*.2)*(isElite?1.7:1),goldScale=(1+diffNorm*.4)*(isElite?1.7:1);
const newEnemy={_id:++enemyIdCounter,et:idx,a:def.a,th:def.th||0,name:def.n,p:def.p,v:def.v,w:def.w,x,y,r:def.r,hp:enemyHp,maxHp:enemyHp,atk:enemyAtk,spd:enemySpd,xp:Math.max(0,Math.round(def.xp*rewardScale)),g:Math.max(0,Math.round(def.g*goldScale)),phase:rand(0,6),hit:0,squash:0,attackCd:rand(.2,1.2),elite:isElite,boss:!!def.boss,pounceTimer:rand(1.5,3),charging:0,stun:0,slow:0,pull:0,c:def.c,cd:def.cd,ai:def.ai,sm:def.sm,role,skillType,skillBaseCd,skillCd:rand(1.2,3.2),skillFlash:0,summoned:!!(spawnOpts&&spawnOpts.summoned),strafeTimer:rand(.3,1),strafeDir:Math.random()<.5?-1:1,retreating:0,retreatTimer:rand(1,2),invuln:0};
if(def.boss){attachBossConfig(newEnemy,def);newEnemy._cdM=BOSS_BUFF.cd(diffNorm);newEnemy._castM=BOSS_BUFF.cast;}enemies.push(newEnemy);
if(def.boss){beginBossCutscene(newEnemy);}}
function enemyProjectile(e,angle,dmg,opts={}){dmg=bossDamageCap(e,Number.isFinite(opts.damageMult)?opts.damageMult:1);const speed=opts.speed||360,style=opts.style||'orb',life=opts.life||1.7;projectiles.push({x:e.x+Math.cos(angle)*(e.r+8),y:e.y+Math.sin(angle)*(e.r+8),vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,dmg,life,color:opts.color||e.c,r:opts.r||5,pat:opts.pat||'orb',style,fromEnemy:true,fromBoss:!!e.boss,sourceEnemy:e,damageMult:opts.damageMult||1,homing:opts.homing||0,targetPlayer:true,explodeR:opts.explodeR||0,explodeColor:opts.explodeColor||e.c,status:opts.status||null});burst(e.x+Math.cos(angle)*e.r,e.y+Math.sin(angle)*e.r,opts.color||e.c,4,{spd:90,life:[.15,.3]});}
function enemyAttack(e,d,dx,dy){const a=Math.atan2(dy,dx);if(e.role==='ranged'&&d>90&&d<520&&e.attackCd<=0){e.attackCd=Math.max(.65,1.45-e.sm*.35-stageIndex*.008);const lead=Math.min(.55,d/520),pa=Math.atan2(player.y+player.dirY*70*lead-e.y,player.x+player.dirX*70*lead-e.x);enemyProjectile(e,pa,e.atk*.95,{speed:470,style:'arrow',pat:'arrow',r:4,life:1.5});return;}
if(e.role==='mage'&&d>100&&d<470&&e.attackCd<=0){e.attackCd=Math.max(.9,1.9-e.sm*.4-stageIndex*.01);for(let i=-1;i<=1;i++)enemyProjectile(e,a+i*.13,e.atk*(i===0?1:.58),{speed:300+stageIndex*2,style:'magic',r:i===0?7:5,life:1.9,explodeR:e.elite?24:0});return;}
if(d<e.r+player.r+8&&e.attackCd<=0&&player.inv<=0&&!dying){let dmg=bossDamageCap(e,1);if(player.defendTimer>0){const red=clamp(Number.isFinite(player.shieldReduction)?player.shieldReduction:.5,0,.85);dmg=Math.round(dmg*(1-red));if(player.shieldReflect){e.hp=Math.max(0,e.hp-Math.max(0,Math.round(e.atk*player.shieldReflect)));}}hp=Math.max(0,hp-Math.max(0,Math.round(Number.isFinite(dmg)?dmg:0)));e.attackCd=Math.max(.42,e.elite?.62:.78);player.inv=.4;floatText(player.x+rand(-6,6),player.y-28,'-'+dmg,'#ff7182');burst(player.x,player.y,'#ff5069',10,{spd:150});addShake(.18);screenFlash(.14);hitStopNow(.05);}}

function killEnemy(idx){const e=enemies[idx];if(!e||e._dead)return;e._dead=true;try{spawnTrpgCorpse(e);}catch(_){}const st=STAGES[stageIndex];if(e.summoned){enemies.splice(idx,1);return;}
try{recordIndex(e);}catch(_){}
const sc=getStageSpawnConfig();const wasBoss=!!e.boss;sfx(wasBoss?'bossdie':'kill');

if(!wasBoss)killsInStage++;
totalKills++;const goldReward=Math.max(0,Math.round((Number.isFinite(e.g)?e.g:0)*(1+(perks.gold||0)*.15))),xpReward=Math.max(0,Math.round(Number.isFinite(e.xp)?e.xp:0));spawnDrops(e,goldReward,xpReward,(Math.random()<.16||(e.elite&&Math.random()<.35)));
floatText(e.x,e.y-8,'+'+xpReward+' XP','#a8ff8b');floatText(e.x+8,e.y+10,'+'+goldReward+'G','#ffd76b');
burst(e.x,e.y-4,e.c,wasBoss?70:20,{spd:wasBoss?340:200,life:[.3,.8]});
hitStopNow(wasBoss?.12:.07);addShake(wasBoss?.8:.16);screenFlash(wasBoss?.65:.08);
enemies.splice(idx,1);
while(Number.isFinite(xp)&&xp>=100)levelUp();

if(wasBoss){const isLast=stageIndex>=STAGES.length-1;stageCleared=true;if(isLast){stageClearTimer=3;toast('👑 BOSS TERAKHIR DIKALAHKAN!');}else{toast('👑 BOSS DIKALAHKAN! PORTAL TERBUKA!');sfx('portal');screenFlash(.65);addShake(.65);const ang=Math.random()*Math.PI*2;portal={x:clamp(player.x+Math.cos(ang)*90,70,WORLD.w-70),y:clamp(player.y+Math.sin(ang)*90,110,WORLD.h-70),r:42,phase:0};}}}
function levelUp(){sfx('level');pendingPerks++;try{setTimeout(openPerkPicker,0);}catch(_e){}level++;hp=maxHp;const bonus=Math.max(0,Math.round(10+level*2));totalGold=Math.min(Number.MAX_SAFE_INTEGER,Math.max(0,(Number.isFinite(totalGold)?totalGold:0)+bonus));xp=Math.max(0,(Number.isFinite(xp)?xp:0)-100);toast('✨ LEVEL UP! Lv.'+level+' → +'+bonus+'G');floatText(player.x,player.y-40,'+'+bonus+' GOLD','#ffd36a',true);burst(player.x,player.y,'#ffd36a',40,{spd:220,life:[.4,.9],grav:60});screenFlash(.2);}

let hudRefreshTimer=0,lastBuffHtml=null;
function updateHud(){
 const hpEl=document.getElementById('hp'),xpEl=document.getElementById('xp');
 hpEl.style.width=clamp(hp/maxHp*100,0,100)+'%';xpEl.style.width=clamp(xp,0,100)+'%';
 document.getElementById('stats').textContent=`HP ${Math.ceil(hp)}/${maxHp} • XP ${xp}/100 • ATK ${Math.round(atk*player.atkMult*player.buffAtkMult*(1+(perks.dmg||0)*.12))}`;
 document.getElementById('goldText').textContent=`💰 ${totalGold}`;document.getElementById('potionText').textContent=`🧪 ${potions}`;
 document.getElementById('kills').textContent=`${killsInStage} KILLS`;updateSurvivalHud();
 document.getElementById('stageProg').textContent=`Stage ${stageIndex+1} / 100`;document.getElementById('stageName2').textContent=STAGES[stageIndex].mapName;
 const tier=getDifficultyTier(stageIndex),tierEl=document.getElementById('diffTier');
 if(tierEl){tierEl.textContent=`${tier.icon} ${tier.fullName}`;tierEl.style.color=tier.color;}
 if(currentChar)document.getElementById('hudName').textContent=`${currentChar.icon} ${currentChar.name} • Lv. ${level}`;
 document.getElementById('hpBarLow').style.display=(running&&hp>0&&hp<maxHp*.35)?'block':'none';
 document.getElementById('skillBtn').classList.toggle('cooling',player.skillCd>0);
 document.getElementById('dashBtn').classList.toggle('cooling',player.dashCd>0);
 document.getElementById('ultBtn').classList.toggle('cooling',player.ultCd>0);
 document.getElementById('ultBtn').classList.toggle('ready',player.ultCd<=0&&running);
 let html='';
 if(player.buffTimer>0)html+=`<div style="color:${player.buffColor||'#fff'}">⚡ ${player.buffTimer.toFixed(1)}s</div>`;
 if(player.defendTimer>0)html+='<div style="color:#80b8ff">🛡️ '+player.defendTimer.toFixed(1)+'s</div>';
 if(player.invisible>0)html+='<div style="color:#c080ff">👻 '+player.invisible.toFixed(1)+'s</div>';
 if(player.regen>0)html+='<div style="color:#80ff80">💚 Regen</div>';
 if(html!==lastBuffHtml){document.getElementById('buffIcons').innerHTML=html;lastBuffHtml=html;}
}

function openShop(context){shopContext=context||'free';renderShop();showScreen('shopScreen');const nb=document.getElementById('shopNext');if(context==='poststage'){nb.style.display='block';nb.textContent='▶ LANJUT';}else nb.style.display='none';}
function closeShop(){hideAllScreens();if(shopContext==='poststage'){shopContext='free';if(stageIndex+1>=STAGES.length){running=false;clearSave();showScreen('win');}else{showStageIntro(stageIndex+1,()=>{startStage(stageIndex+1);running=true;});}}else if(running){}else showScreen('start');}
function getShopPrice(item){const bought=Math.max(0,shopHistory[item.id]||0),growth=item.type==='upgrade' ? .75 : 0;return Math.max(0,Math.round(item.price*(1+bought*growth)));}
/*
  Shop system: handling pembelian item, validasi gold, dan update UI setelah transaksi.
*/
function buyItem(item){const _s0=statSnap();const bought=shopHistory[item.id]||0,price=getShopPrice(item);if(item.maxBuy!==undefined&&bought>=item.maxBuy){toast('❌ Sudah maksimal!');return;}if(totalGold<price){toast('❌ Gold kurang!');return;}totalGold=Math.max(0,totalGold-price);shopHistory[item.id]=bought+1;item.onBuy();toast('✅ '+item.nm+' dibeli!');if(item.id!=='relicbox')statShopPop(item,_s0);sfx('buy');updateHud();renderShop();}
function renderShop(){document.getElementById('shopGold').textContent=totalGold;{const ss=document.getElementById('shopStats');if(ss)ss.innerHTML=statStrip();}const grid=document.getElementById('shopGrid');grid.innerHTML='';SHOP_ITEMS.forEach(item=>{const bought=shopHistory[item.id]||0,price=getShopPrice(item);const maxed=item.maxBuy!==undefined&&bought>=item.maxBuy;const cant=totalGold<price||maxed;const el=document.createElement('button');el.className='shopItem'+(maxed?' owned':'')+(cant&&!maxed?' cant':'');el.innerHTML=`${bought>0?`<div class="qtyTag">×${bought}</div>`:''}${maxed?`<div class="ownedTag">MAX</div>`:''}<div class="ico">${item.ico}</div><div class="nm">${item.nm}</div><div class="desc">${item.desc}</div>${shopPV(item)}<div class="price">💰 ${price}</div>`;if(!cant)el.onclick=()=>buyItem(item);grid.appendChild(el);});}

const SAVE_KEY='eclipse_rpg_manual_save_v2';let stageSnapshot=null;let stageCleared=false;let explicitSaveThisSession=false;
function readSave(){try{const raw=localStorage.getItem(SAVE_KEY);if(!raw)return null;const d=JSON.parse(raw);if(!d||!d.charId||!CHARACTERS[d.charId])return null;return d;}catch(e){return null;}}
function collectSave(stageOverride){if(!currentChar)return null;const si=(stageOverride!=null)?stageOverride:(stageCleared?Math.min(STAGES.length-1,stageIndex+1):stageIndex);return {v:1,ts:Date.now(),charId:currentChar.id||'fighter',stageIndex:clamp(si,0,STAGES.length-1),level,xp,maxHp,hp:Math.ceil(hp),atk,speed:player.speed,shieldReduction:player.shieldReduction,totalGold,potions,totalKills,shopHistory:Object.assign({},shopHistory),perks:Object.assign({},perks)};}
function saveGame(stageOverride){if(!currentChar)return;const d=collectSave(stageOverride);if(!d)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(d));if(localStorage.getItem(SAVE_KEY)===null)throw 0;explicitSaveThisSession=true;}catch(e){try{toast('⚠️ Gagal menyimpan (penyimpanan penuh/diblokir)');}catch(_e){}}refreshContinueUI();}
function clearSave(){try{localStorage.removeItem(SAVE_KEY);}catch(e){}explicitSaveThisSession=false;stageSnapshot=null;refreshContinueUI();}
function refreshContinueUI(){try{updateIndexCard();}catch(_e){}const btn=document.getElementById('toContinue');const info=document.getElementById('saveInfo');const banner=document.getElementById('continueBanner');if(!btn)return;const d=readSave();if(!d){btn.style.display='none';if(info)info.style.display='none';if(banner)banner.style.display='none';return;}const ch=CHARACTERS[d.charId]||CHARACTERS[0];const idx=clamp(d.stageIndex|0,0,STAGES.length-1);const st=STAGES[idx]||{mapName:'Dunia Eclipse'};btn.style.display='grid';btn.textContent='▶';btn.setAttribute('aria-label',`Lanjutkan Stage ${idx+1}`);btn.title=`Lanjutkan Stage ${idx+1}`;if(banner)banner.style.display='flex';if(info){info.style.display='block';info.innerHTML=`Stage ${idx+1} / 100 · ${ch.icon||''} ${ch.name||'Pahlawan'} • Lv.${d.level||1}<br><span style="opacity:.75">${st.mapName||'Dunia Eclipse'}</span>`;}}
function continueGame(){explicitSaveThisSession=false;const d=readSave();if(!d){menuNote('❌ Tidak ada simpanan');refreshContinueUI();return;}const ch=CHARACTERS[d.charId];currentChar=ch;currentChar.id=d.charId;selectedCharId=d.charId;level=Math.max(1,(d.level|0)||1);xp=clamp(d.xp|0,0,99);maxHp=Math.max(1,(d.maxHp|0)||ch.hp);const rawHp=(d.hp==null?maxHp:(d.hp|0));hp=clamp(Math.max(rawHp,Math.ceil(maxHp*0.5)),1,maxHp);atk=Math.max(1,(d.atk|0)||ch.atk);player.speed=(d.speed|0)||ch.speed;player.shieldReduction=(d.shieldReduction!=null)?d.shieldReduction:0.5;totalGold=Math.max(0,d.totalGold|0);potions=Math.max(0,d.potions|0);totalKills=Math.max(0,d.totalKills|0);shopHistory=d.shopHistory?Object.assign({},d.shopHistory):{};perks=sanitizePerks(d.perks);pendingPerks=0;drops.length=0;perkOpen=false;stageIndex=clamp(d.stageIndex|0,0,STAGES.length-1);dying=false;paused=false;timeScale=1;applyCharButtons();enterFullscreen();showLoading('Memulihkan data petualangan...',()=>{showStageIntro(stageIndex,()=>{startStage(stageIndex);running=true;toast('💾 Progress dimuat — Stage '+(stageIndex+1));});});}

