function showScreen(id){document.querySelectorAll('.screen').forEach(el=>el.classList.remove('active'));const lobby=document.getElementById('start');lobby.classList.remove('lobby-backdrop');if(id)document.getElementById(id).classList.add('active');if(['indexScreen','settingsScreen','aboutScreen'].includes(id)){lobby.classList.add('active','lobby-backdrop');}if(id==='start'||id==='charSel'){document.body.classList.add('game-playing');if(id==='start')refreshContinueUI();requestAnimationFrame(()=>{enterFullscreen();updateFullscreenPrompt();});}else if(id&&id!=='loadingScreen'){document.body.classList.add('game-playing');}}
