function showStageIntro(idx,cb){
 const st=STAGES[idx];if(!st)return;
 const token=++stageTransitionToken;stageTransitionLock=true;hardResetCanvasSurface();
 const tier=getDifficultyTier(idx),pct=Math.round(getStageDifficulty(idx)*100);
 document.getElementById('siNum').textContent=`STAGE ${idx+1} / 100`;document.getElementById('siName').textContent=st.mapName;document.getElementById('siDesc').textContent=st.desc;
 const tEl=document.getElementById('siTier');if(tEl){tEl.textContent=`${tier.icon} ${tier.fullName} — ${tier.desc} (${pct}%)`;tEl.style.color=tier.color;}
 showScreen('stageIntro');
 setTimeout(()=>{if(token!==stageTransitionToken)return;hideAllScreens();cb&&cb();},1700);
}
