document.querySelectorAll('#charTabs button').forEach(btn=>{btn.onclick=()=>{document.querySelectorAll('#charTabs button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');currentCharCat=btn.getAttribute('data-cat');buildCharCards();};});
function renderCharacterInfo(id){const ch=CHARACTERS[id];if(!ch)return;const box=document.getElementById('charInfo');const skills=[['SKILL 1',ch.sk1],['SKILL 2',ch.sk2],['ULTIMATE',ch.ult]];const role={melee:'THE WARRIOR',magic:'THE MAGE',ranged:'THE RANGER',special:'THE SPECIALIST',summoner:'THE SUMMONER',hybrid:'THE HYBRID'}[ch.cat]||String(ch.cat||'HERO').toUpperCase();box.innerHTML=`<div class="charInfoHead"><div class="charInfoIcon">${ch.icon}</div><div><div class="charInfoName" style="color:${ch.color}">${ch.name}</div><div class="charInfoRole">${role}</div></div></div><div class="charInfoSub">${ch.sub}</div><div class="skillInfoGrid">${skills.map(([slot,sk])=>{const d=describeSkill(sk,slot);return `<div class="skillInfo"><div class="siTop"><span>${sk.icon}</span><span>${slot} · ${sk.name}</span></div><div class="siDesc">${d.desc}</div><span class="siCd">⏱️ Cooldown ${d.cd}s</span></div>`}).join('')}</div>`;
const set=(id,val)=>{const e=document.getElementById(id);if(e)e.textContent=val;};set('detailName',ch.name);set('portraitName',ch.name);set('selectedHeroLabel',ch.name);set('detailRole',role);set('portraitSub',role);set('detailDesc',`${ch.sub}. Pilih ${ch.name} untuk menjelajahi 100 dunia Eclipse dan menghadapi monster serta boss unik.`);const ps=document.getElementById('portraitSkills');if(ps)ps.innerHTML=[ch.sk1.icon,ch.sk2.icon,ch.ult.icon].map(x=>`<span>${x}</span>`).join('');const pct=(v,max)=>Math.max(12,Math.min(100,Math.round((v/max)*100)))+'%';[['barAtk',ch.atk,30],['barHp',ch.hp,180],['barSpd',ch.speed,260],['portraitAtk',ch.atk,30],['portraitHp',ch.hp,180],['portraitSpd',ch.speed,260]].forEach(([eid,v,m])=>{const e=document.getElementById(eid);if(e)e.style.width=pct(v,m)});const pc=document.getElementById('heroPortrait');if(pc){const g=pc.getContext('2d');g.clearRect(0,0,pc.width,pc.height);g.save();g.translate(pc.width/2,pc.height*.73);g.scale(4.8,4.8);g.fillStyle='rgba(0,0,0,.38)';g.beginPath();g.ellipse(0,17,17,5,0,0,Math.PI*2);g.fill();drawHero(g,ch,1,0,{});g.restore();}}
// Character preview animation: each hero keeps its own archetype, color and idle/attack motion.
const portraitCanvas=document.getElementById('heroPortrait');
const portraitOriginalParent=portraitCanvas?portraitCanvas.parentElement:null;
const portraitPlaceholder=document.createComment('heroPortrait original position');
if(portraitCanvas&&portraitOriginalParent)portraitOriginalParent.insertBefore(portraitPlaceholder,portraitCanvas);
const mobilePortraitLabel=document.createElement('div');mobilePortraitLabel.className='mobilePortraitLabel';mobilePortraitLabel.textContent='✦ ANIMASI KARAKTER AKTIF ✦';
function placePortraitForViewport(){
  if(!portraitCanvas||!portraitOriginalParent)return;
  if(window.matchMedia('(max-width: 600px)').matches){
    const details=document.querySelector('.heroDetails');
    if(details&&portraitCanvas.parentElement!==details){details.insertBefore(mobilePortraitLabel,details.firstChild);details.insertBefore(portraitCanvas,details.children[1]||null);}
  }else if(portraitCanvas.parentElement!==portraitOriginalParent){
    portraitOriginalParent.insertBefore(portraitCanvas,portraitPlaceholder.nextSibling);
    mobilePortraitLabel.remove();
  }
}
placePortraitForViewport();window.addEventListener('resize',placePortraitForViewport,{passive:true});
let portraitAnimFrame=0,portraitLast=0,portraitClock=0;
function animateSelectedPortrait(ts){
  const selScreen=document.getElementById('charSel');
  if(!document.hidden&&selScreen&&selScreen.classList.contains('active')&&ts-portraitLast>40){
    portraitLast=ts;portraitClock+=.045;
    const id=selectedCharId||(currentChar?currentChar.id:'fighter');const ch=CHARACTERS[id];
    if(ch&&portraitCanvas){const g=portraitCanvas.getContext('2d');g.clearRect(0,0,portraitCanvas.width,portraitCanvas.height);g.save();g.translate(portraitCanvas.width/2,portraitCanvas.height*.73+Math.sin(portraitClock*2.2)*2);const scale=Math.min(portraitCanvas.width/68,portraitCanvas.height/100,5.1);g.scale(scale,scale);g.fillStyle='rgba(0,0,0,.4)';g.beginPath();g.ellipse(0,17,17,5,0,0,Math.PI*2);g.fill();const attackPulse=(Math.sin(portraitClock*1.7)>0.94)?0.34:0;drawHero(g,ch,Math.sin(portraitClock*.6)>=0?1:-1,attackPulse,{walkT:portraitClock,walking:true,dashing:Math.sin(portraitClock*.8)>0.985});g.restore();}
  }
  portraitAnimFrame=requestAnimationFrame(animateSelectedPortrait);
}
if(portraitCanvas)portraitAnimFrame=requestAnimationFrame(animateSelectedPortrait);

function updateFullscreenPrompt(){const b=document.getElementById('fullscreenPrompt');if(!b)return;const isFull=!!(document.fullscreenElement||document.webkitFullscreenElement);b.classList.toggle('show',!isFull);b.textContent=(window.matchMedia('(orientation:portrait)').matches?'↻ PUTAR HP, LALU ':'⛶ ')+(isFull?'MODE LAYAR PENUH AKTIF':'AKTIFKAN LANDSCAPE & FULLSCREEN');}
function enterFullscreen(){const el=document.documentElement;document.body.classList.add('game-playing');let req=null;try{if(!document.fullscreenElement&&!document.webkitFullscreenElement){if(el.requestFullscreen)req=el.requestFullscreen({navigationUI:'hide'});else if(el.webkitRequestFullscreen)req=el.webkitRequestFullscreen();}if(req&&req.then)req.then(()=>{lockLandscape();updateFullscreenPrompt();}).catch(()=>updateFullscreenPrompt());else{lockLandscape();updateFullscreenPrompt();}}catch(e){updateFullscreenPrompt();}}
function lockLandscape(){try{if(screen.orientation&&screen.orientation.lock){const p=screen.orientation.lock('landscape');if(p&&p.catch)p.catch(()=>{});}}catch(e){}}
document.addEventListener('fullscreenchange',()=>{if(document.fullscreenElement){document.body.classList.add('game-playing');lockLandscape();}updateFullscreenPrompt();});
document.addEventListener('webkitfullscreenchange',updateFullscreenPrompt);
const fullscreenPromptButton=document.getElementById('fullscreenPrompt');if(fullscreenPromptButton)fullscreenPromptButton.addEventListener('click',enterFullscreen);
// Browser requires a real user gesture for fullscreen on many mobile browsers; the first tap tries automatically.
document.addEventListener('pointerdown',()=>{const active=document.querySelector('.screen.active');if(active&&['start','charSel'].includes(active.id)&&!document.fullscreenElement&&!document.webkitFullscreenElement)enterFullscreen();},{capture:true,passive:true});
function showLoading(status,callback){const screenEl=document.getElementById('loadingScreen'),fill=document.getElementById('loadingFill'),pct=document.getElementById('loadingPercent'),label=document.getElementById('loadingStatus'),tip=document.getElementById('loadingTip');const tips=['Tips: Kalahkan boss untuk membuka portal menuju dunia berikutnya.','Tips: Gunakan dash untuk menghindari serangan area boss.','Tips: Setiap pahlawan memiliki kombinasi skill yang berbeda.','Tips: Kumpulkan gold untuk membeli peningkatan di toko.'];let progress=0;label.textContent=status||'Membangunkan dunia...';tip.textContent=tips[Math.floor(Math.random()*tips.length)];fill.style.width='0%';pct.textContent='0%';showScreen('loadingScreen');const start=performance.now();const duration=1850;function tick(now){progress=Math.min(100,Math.round((now-start)/duration*100));fill.style.width=progress+'%';pct.textContent=progress+'%';if(progress<100){requestAnimationFrame(tick);}else{setTimeout(()=>{if(screenEl.classList.contains('active'))callback&&callback();},180);}}requestAnimationFrame(tick);}
function buildCharCards(){const cont=document.getElementById('charCards');const prevScroll=cont.scrollTop;cont.innerHTML='';let sel=selectedCharId||(currentChar?currentChar.id:'fighter');if(!isCharUnlocked(sel)){sel='fighter';selectedCharId=sel;}const entries=Object.entries(CHARACTERS).filter(([id,ch])=>{if(currentCharCat==='all')return true;return ch.cat===currentCharCat;});document.getElementById('charCount').textContent=unlockedCharCount(maxStageReached);
entries.forEach(([id,ch])=>{const card=document.createElement('button');const _ul=isCharUnlocked(id);card.className='card'+(id===sel?' sel':'')+(_ul?'':' locked');card.setAttribute('data-id',id);const catLabel={melee:'MELEE',magic:'MAGIC',ranged:'RANGED',special:'SPECIAL',summoner:'SUMMONER',hybrid:'HYBRID'}[ch.cat]||'';card.innerHTML=`<div class="clsTag cls-${ch.cat||'melee'}">${catLabel}</div><div class="previewWrap"><canvas class="preview" width="96" height="96"></canvas></div><div class="nm" style="color:${ch.color}">${ch.name}</div><div class="sub2">${ch.sub}</div><div class="stats2"><span>❤️${ch.hp}</span><span>⚔️${ch.atk}</span><span>💨${ch.speed}</span></div>${_ul?'':'<div class="lockTag">🔒 STAGE '+unlockStageFor(charIndexOf(id))+'</div>'}`;card.onclick=()=>{if(!_ul){menuNote('🔒 Terbuka di Stage '+unlockStageFor(charIndexOf(id)));return;}selectedCharId=id;renderCharacterInfo(id);cont.querySelectorAll('.card').forEach(el=>el.classList.remove('sel'));card.classList.add('sel');};cont.appendChild(card);
const prev=card.querySelector('.preview'),pctx=prev.getContext('2d');pctx.imageSmoothingEnabled=false;pctx.clearRect(0,0,96,96);pctx.save();pctx.translate(48,70);pctx.scale(1.12,1.12);pctx.fillStyle='rgba(0,0,0,.35)';pctx.beginPath();pctx.ellipse(0,16,15,5,0,0,Math.PI*2);pctx.fill();drawHero(pctx,ch,1,0,{});pctx.restore();});
cont.scrollTop=prevScroll;renderCharacterInfo(sel);
document.getElementById('charNext').onclick=()=>{const id=selectedCharId||(currentChar?currentChar.id:'fighter');if(!isCharUnlocked(id)){menuNote('🔒 Karakter belum terbuka');return;}currentChar=CHARACTERS[id];currentChar.id=id;applyCharButtons();enterFullscreen();beginRun();};}

// Lightweight individual idle animations for visible hero cards in the roster.
let rosterAnimClock=0,rosterLastFrame=0;
function animateRosterCards(ts){const charScreen=document.getElementById('charSel');if(!document.hidden&&charScreen&&charScreen.classList.contains('active')&&ts-rosterLastFrame>66){rosterLastFrame=ts;rosterAnimClock+=.07;const cards=document.querySelectorAll('#charCards .card');for(const card of cards){const r=card.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight||r.right<0||r.left>innerWidth)continue;const id=card.getAttribute('data-id'),ch=CHARACTERS[id],cv=card.querySelector('canvas.preview');if(!ch||!cv)continue;const g=cv.getContext('2d');g.clearRect(0,0,cv.width,cv.height);g.save();g.translate(cv.width/2,70+Math.sin(rosterAnimClock*2+(id.length*.7))*1.6);g.scale(1.12,1.12);g.fillStyle='rgba(0,0,0,.35)';g.beginPath();g.ellipse(0,16,15,5,0,0,Math.PI*2);g.fill();const pulse=Math.sin(rosterAnimClock*1.8+id.length)>0.965?.22:0;drawHero(g,ch,Math.sin(rosterAnimClock*.55+id.length)>=0?1:-1,pulse,{walkT:rosterAnimClock+id.length,walking:true,dashing:Math.sin(rosterAnimClock+id.length)>0.99});g.restore();}}requestAnimationFrame(animateRosterCards);}
requestAnimationFrame(animateRosterCards);

