function startStage(idx){fxClear();flushDrops();/* HARD RESET STAGE RENDER STATE */
stageTransitionToken++;stageTransitionLock=true;
STAGE_BG=null;gameActions.length=0;drawQueueUsed=0;
hardResetCanvasSurface();
document.body.classList.remove('cutscene');bossCutscene.active=false;bossCutscene.boss=null;bossCutscene.state='';cameraZoom=1;document.getElementById('game').classList.remove('cine');document.body.classList.add('game-playing');fitGameToScreen();stageIndex=idx;killsInStage=0;stageClearTimer=0;survivalDurationCurrent=getSurvivalDuration(idx);survivalRemaining=survivalDurationCurrent;survivalExpired=false;portal=null;portalFx.active=false;portalFx.t=0;portalFx.done=false;enemies=[];projectiles=[];rainArrows=[];meteors=[];allies=[];particles=[];floating=[];dashGhosts=[];footprints=[];ripples=[];leaves=[];slashArcs=[];SKILL_VFX.length=0;currentAimTarget=null;warningZones=[];
player.x=WORLD.w/2;player.y=WORLD.h/2;player.inv=1.5;
player.attackCd=player.skillCd=player.dashCd=player.ultCd=0;player.dodge=DODGE.max;player.dodgeT=0;
player.dashTime=player.defendTimer=player.attackAnim=0;
player.buffTimer=0;player.buffAtkMult=1;player.buffSpeedMult=1;
player.lifesteal=0;player.invisible=0;player.regen=0;player.isDashing=false;
if(player.status){player.status.poison=0;player.status.burn=0;player.status.freeze=0;player.status.shock=0;player.status.slow=0;}
genWorld();
hardResetCanvasSurface();stageTransitionLock=false;
const st=STAGES[idx];const spawnCfg=getStageSpawnConfig();
const initialCount=st.pool.length===0?1:Math.min(spawnCfg.cap,Math.max(1,spawnCfg.initial));
for(let i=0;i<initialCount;i++)spawnEnemy();
document.getElementById('zone').textContent=st.mapName;
stageCleared=false;
updateHud();updateCamera(1);
stageSnapshot=collectSave();try{markStageReached(idx+1);}catch(_e){}if(idx>=1){try{saveGame(idx);toast('💾 Tersimpan otomatis — Stage '+(idx+1));}catch(_e){}}try{setTimeout(openPerkPicker,0);}catch(_e){}}
function beginRun(){bossMem={sk:0,dash:0,ult:0};explicitSaveThisSession=false;level=1;xp=0;maxHp=currentChar.hp;hp=maxHp;atk=currentChar.atk;player.speed=currentChar.speed;player.shieldReduction=0.5;totalGold=0;potions=0;totalKills=0;stageIndex=0;shopHistory={};perks={};pendingPerks=0;drops.length=0;perkOpen=false;genWorld();showLoading('Memuat karakter dan dunia pertama...',()=>{showStageIntro(0,()=>{startStage(0);running=true;});});}
document.getElementById('retryStage').addEventListener('click',()=>{hp=maxHp;enterFullscreen();showLoading('Menyiapkan ulang medan perang...',()=>{showStageIntro(stageIndex,()=>{startStage(stageIndex);running=true;});});});
