const SHADER_THEME={
 forest:{tint:'#3f9a52',a:.16,glow:'#d8ffb0',rays:'#fff2b0',kind:'float',col:'#d9ff9e',vx:6,vy:-4},
 meadow:{tint:'#ffe9a0',a:.2,glow:'#fff0b0',rays:'#fff6c0',kind:'float',col:'#fff3a8',vx:8,vy:-5},
 ruins:{tint:'#c9a46a',a:.16,glow:'#ffe2b0',kind:'dust',col:'#e6d3ad',vx:14,vy:2},
 rocky:{tint:'#8aa4c8',a:.15,glow:'#d6e6ff',kind:'dust',col:'#c8d4e2',vx:16,vy:3},
 shadow:{tint:'#6a2fa0',a:.28,glow:'#c78bff',kind:'wisp',col:'#c58cff',vx:5,vy:-9,fog:'#3a1a5a'},
 mushroom:{tint:'#d855a8',a:.18,glow:'#ffa0e0',kind:'spore',col:'#ffb2ea',vx:4,vy:-8,fog:'#6a2a5a'},
 water:{tint:'#2092d6',a:.2,glow:'#9ff2ff',kind:'bubble',col:'#c8fbff',vx:2,vy:-22,caustic:true},
 snow:{tint:'#bfe6ff',a:.16,glow:'#e8f7ff',kind:'snow',col:'#ffffff',vx:-18,vy:42},
 lava:{tint:'#ff4a10',a:.24,glow:'#ff9a40',kind:'ember',col:'#ffa040',vx:8,vy:-46,heat:true,pulse:true},
 desert:{tint:'#ffbe68',a:.22,glow:'#ffe4a8',kind:'dust',col:'#f2d49a',vx:70,vy:6},
 bamboo:{tint:'#8ad064',a:.14,glow:'#e4ffb0',rays:'#e8ffc0',kind:'float',col:'#d6ff9e',vx:7,vy:-3},
 sky:{tint:'#fff0c8',a:.2,glow:'#ffffff',rays:'#ffffff',kind:'cloud',col:'#ffffff',vx:22,vy:0},
 tech:{tint:'#20d6ff',a:.18,glow:'#7ef0ff',kind:'data',col:'#5af0ff',vx:0,vy:38,scan:true}
};
let SCAN_PATTERN=null;
function _mod(a,b){return ((a%b)+b)%b;}
function drawShaderPost(st){
 const lv=+settings.shader;if(!(lv>0)||!W||!H)return;
 const quality=getPerformanceRank(),th=SHADER_THEME[st.theme]||SHADER_THEME.forest,t=worldTime,depth=stageIndex/99,big=lv>1;
 ctx.save();ctx.setTransform(dpr,0,0,dpr,0,0);ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
 ctx.globalCompositeOperation='soft-light';
 ctx.globalAlpha=Math.min(1,th.a*(big?1.35:1)*(th.pulse?1+Math.sin(t*2.2)*.25:1)+depth*.05);
 ctx.fillStyle=th.tint;ctx.fillRect(0,0,W,H);
 ctx.globalCompositeOperation='lighter';
 if(th.rays&&quality>0){
  const n=quality===2?(big?5:3):1;
  for(let i=0;i<n;i++){
   const x0=((i*.27+.06)*W)+Math.sin(t*.22+i*1.7)*46-camX*.04,wd=60+i*16,sk=H*.5;
   const gr=ctx.createLinearGradient(x0,0,x0-sk,H);gr.addColorStop(0,th.rays);gr.addColorStop(1,'rgba(0,0,0,0)');
   ctx.globalAlpha=(.07+.03*Math.sin(t*.8+i*2))*(big?1.3:1);ctx.fillStyle=gr;
   ctx.beginPath();ctx.moveTo(x0,-10);ctx.lineTo(x0+wd,-10);ctx.lineTo(x0+wd-sk,H);ctx.lineTo(x0-sk,H);ctx.closePath();ctx.fill();
  }
 }
 if(th.caustic&&quality>0){
  ctx.strokeStyle='#9ff6ff';ctx.lineWidth=2;
  const lines=quality===2?(big?12:7):3;
  for(let i=0;i<lines;i++){
   const y=(i+.5)*H/lines+Math.sin(t*.7+i)*12-_mod(camY*.12,H/lines);
   ctx.globalAlpha=.06+.03*Math.sin(t*1.3+i);ctx.beginPath();
   for(let x=0;x<=W+24;x+=24){const yy=y+Math.sin(x*.021+t*1.4+i*1.3)*7+Math.sin(x*.047-t*.9)*3;if(x)ctx.lineTo(x,yy);else ctx.moveTo(x,yy);}
   ctx.stroke();
  }
 }
 if(th.heat){
  const gr=ctx.createLinearGradient(0,H*.55,0,H);gr.addColorStop(0,'rgba(255,60,10,0)');gr.addColorStop(1,'rgba(255,90,20,1)');
  ctx.globalAlpha=.16+.06*Math.sin(t*3);ctx.fillStyle=gr;ctx.fillRect(0,H*.55,W,H*.45);
 }
 const N=Math.round((big?46:24)*(th.kind==='snow'||th.kind==='ember'?1.3:1)*getCosmeticScale());
 ctx.fillStyle=th.col;ctx.strokeStyle=th.col;
 for(let i=0;i<N;i++){
  const h1=_mod(Math.sin(i*12.9898)*43758.5453,1),h2=_mod(Math.sin(i*78.233+3.1)*12345.678,1),h3=_mod(Math.sin(i*39.346+7.7)*9871.31,1);
  const par=.15+h2*.35;
  let x=_mod(h1*W+t*th.vx*(.5+h2)-camX*par+Math.sin(t*.9+i)*8,W);
  let y=_mod(h3*H+t*th.vy*(.5+h2)-camY*par,H);
  const tw=.45+.55*Math.sin(t*2.4+i*1.9);
  const k=th.kind;
  if(k==='snow'){ctx.globalAlpha=.7;const s=1.5+h2*2.5;ctx.fillRect(x|0,y|0,s,s);}
  else if(k==='ember'){ctx.globalAlpha=.8*tw;const s=1.5+h2*2.5;ctx.fillStyle=h2>.6?'#ffd060':'#ff7a30';ctx.fillRect(x|0,y|0,s,s);}
  else if(k==='bubble'){ctx.globalAlpha=.3;ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,2+h2*4,0,6.283);ctx.stroke();}
  else if(k==='data'){ctx.globalAlpha=.5*tw;ctx.fillRect(x|0,y|0,2,6+h2*8);}
  else if(k==='cloud'){ctx.globalAlpha=.07;ctx.fillRect(x|0,y|0,60+h2*90,8+h2*8);}
  else if(k==='dust'){ctx.globalAlpha=.3;ctx.fillRect(x|0,y|0,2+h2*6,1.5);}
  else if(k==='wisp'||k==='spore'){
   const r=5+h2*10,gr=ctx.createRadialGradient(x,y,0,x,y,r);gr.addColorStop(0,th.col);gr.addColorStop(1,'rgba(0,0,0,0)');
   ctx.globalAlpha=.35*tw;ctx.fillStyle=gr;ctx.fillRect(x-r,y-r,r*2,r*2);ctx.fillStyle=th.col;
  }
  else{ctx.globalAlpha=.55*tw;const s=1.5+h2*2;ctx.fillRect(x|0,y|0,s,s);}
 }
 // cahaya hero + boss (bloom sederhana)
 if(running||paused){
  const px=player.x-camX,py=player.y-camY,R=big?210:170;
  let gr=ctx.createRadialGradient(px,py,6,px,py,R);gr.addColorStop(0,th.glow);gr.addColorStop(1,'rgba(0,0,0,0)');
  ctx.globalAlpha=.2+.03*Math.sin(t*3);ctx.fillStyle=gr;ctx.fillRect(px-R,py-R,R*2,R*2);
  if(big)for(const e of enemies){
   if(!e.boss)continue;
   const ex=e.x-camX,ey=e.y-camY,rr2=e.r*3.2;
   if(ex<-rr2||ex>W+rr2||ey<-rr2||ey>H+rr2)continue;
   gr=ctx.createRadialGradient(ex,ey,4,ex,ey,rr2);gr.addColorStop(0,e.c);gr.addColorStop(1,'rgba(0,0,0,0)');
   ctx.globalAlpha=.22+.06*Math.sin(t*4);ctx.fillStyle=gr;ctx.fillRect(ex-rr2,ey-rr2,rr2*2,rr2*2);
  }
 }
 ctx.globalCompositeOperation='source-over';
 if(th.fog){
  for(let i=0;i<3;i++){
   const fx=_mod(i*W*.45+t*(10+i*4)-camX*.1,W+500)-250,fy=H*(.25+i*.28)+Math.sin(t*.3+i)*30,fr=260+i*60;
   const gr=ctx.createRadialGradient(fx,fy,10,fx,fy,fr);gr.addColorStop(0,th.fog);gr.addColorStop(1,'rgba(0,0,0,0)');
   ctx.globalAlpha=big?.34:.24;ctx.fillStyle=gr;ctx.fillRect(fx-fr,fy-fr,fr*2,fr*2);
  }
 }
 if(th.scan&&big){
  if(!SCAN_PATTERN){const c=document.createElement('canvas');c.width=4;c.height=4;const g=c.getContext('2d');g.fillStyle='rgba(0,20,40,.55)';g.fillRect(0,0,4,1);SCAN_PATTERN=ctx.createPattern(c,'repeat');}
  ctx.globalAlpha=.22;ctx.fillStyle=SCAN_PATTERN;ctx.fillRect(0,0,W,H);
 }
 // vignette
 const vr=Math.hypot(W,H)*.62,vg=ctx.createRadialGradient(W/2,H/2,vr*.38,W/2,H/2,vr);
 vg.addColorStop(0,'rgba(0,0,0,0)');vg.addColorStop(1,st.theme==='snow'||st.theme==='sky'?'rgba(10,20,40,.5)':'rgba(0,0,0,.72)');
 ctx.globalAlpha=Math.min(.95,.55+depth*.35+(big?.1:0));ctx.fillStyle=vg;ctx.fillRect(0,0,W,H);
 ctx.restore();
}

/* ===== INDEX MAKHLUK (monster & boss) ===== */
const IDX_KEY='eclipse_rpg_index_v1';
let indexData={},idxFilter='all',idxReturn='start',idxSaveT=0;
function loadIndex(){try{const r=localStorage.getItem(IDX_KEY);if(r){const d=JSON.parse(r);if(d&&typeof d==='object')indexData=d;}}catch(e){indexData={};}}
function saveIndexNow(){try{localStorage.setItem(IDX_KEY,JSON.stringify(indexData));}catch(e){}}
function saveIndexSoon(){clearTimeout(idxSaveT);idxSaveT=setTimeout(saveIndexNow,1200);}
addEventListener('pagehide',saveIndexNow);
// Hapus checkpoint bila halaman ditutup/ditinggalkan saat sesi aktif tanpa Save & Quit.
addEventListener('pagehide',()=>{/* fixpack: checkpoint terakhir dipertahankan */});

document.addEventListener('visibilitychange',()=>{if(document.hidden)saveIndexNow();});
const PAT_LORE={slime:'Makhluk lembek yang memantul liar. Lemah sendirian, merepotkan bila bergerombol.',humanoid:'Petarung berakal yang memakai senjata dan taktik sederhana.',golem:'Raksasa batu atau logam yang lambat tetapi menghantam sangat keras.',robot:'Mesin tempur dingin yang bergerak tanpa belas kasihan.',bug:'Makhluk berkaki banyak dengan cangkang keras dan bisa berbahaya.',mushroom:'Jamur hidup yang menebar spora beracun ke sekelilingnya.',bat:'Pemburu udara yang gesit dan sulit dibidik.',beast:'Binatang buas yang menerkam dengan kecepatan tinggi.',imp:'Iblis kecil licik yang gemar melempar api dan sihir.',demon:'Penguasa kegelapan dengan kekuatan sihir yang menghancurkan.',winged:'Penguasa langit yang menyerang dari ketinggian.',treant:'Pohon purba yang terbangun untuk melindungi hutannya.',ghost:'Roh gentayangan yang melayang menembus kegelapan.',jellyfish:'Makhluk laut berselaput yang menyengat dengan aliran listrik.',worm:'Cacing raksasa yang menyerbu dari balik tanah dan air.',dragon:'Naga perkasa yang disegani seluruh makhluk di dunianya.',king:'Penguasa bermahkota yang memimpin pasukannya sendiri.'};
const PAT_ICON={slime:'💧',humanoid:'🗡️',golem:'🪨',robot:'⚙️',bug:'🕷️',mushroom:'🍄',bat:'🦇',beast:'🐺',imp:'👿',demon:'😈',winged:'🪽',treant:'🌳',ghost:'👻',jellyfish:'🪼',worm:'🪱',dragon:'🐉',king:'👑'};
function idxSprite(def,locked,size){
 const cv=document.createElement('canvas');cv.width=cv.height=size;
 const g=cv.getContext('2d');g.imageSmoothingEnabled=false;
 if(trpgIcon(def,size,g)){if(locked){g.globalCompositeOperation='source-in';g.fillStyle='#0a1226';g.fillRect(0,0,size,size);}return cv;}
 const ai=getEnemyAtlasIndex({a:def.a,n:def.n},def.p);
 let sp=ENEMY_ATLAS.sprites[ai];
 if(sp&&def.th)sp=getTintedSprite(ai,def.th)||sp;
 if(sp){
  const sc=Math.min((size-8)/sp.width,(size-8)/sp.height),w=sp.width*sc,h=sp.height*sc;
  g.drawImage(sp.canvas,sp.x,sp.y,sp.width,sp.height,Math.round((size-w)/2),Math.round((size-h)/2),Math.round(w),Math.round(h));
 }else{
  g.fillStyle=def.c||'#888';g.beginPath();g.arc(size/2,size/2,size*.32,0,6.283);g.fill();
  g.fillStyle=def.cd||'#444';g.fillRect(size*.38,size*.42,size*.08,size*.08);g.fillRect(size*.54,size*.42,size*.08,size*.08);
 }
 if(locked){g.globalCompositeOperation='source-in';g.fillStyle='#0a1226';g.fillRect(0,0,size,size);}
 return cv;
}
function idxCounts(){let m=0,b=0,mt=0,bt=0;for(let i=0;i<ET.length;i++){const f=!!indexData[i];if(ET[i].boss){bt++;if(f)b++;}else{mt++;if(f)m++;}}return{m,b,mt,bt,all:m+b,tot:mt+bt};}
function updateIndexCard(){
 const c=idxCounts(),n=document.getElementById('indexCardNum'),b=document.getElementById('indexCardBar');
 if(n)n.textContent=c.all+' / '+c.tot;
 if(b)b.style.width=(c.tot?c.all/c.tot*100:0)+'%';
}
function recordIndex(e){
 if(!e||e.et===undefined)return;
 const def=ET[e.et];if(!def)return;
 const rec=indexData[e.et];
 if(!rec){indexData[e.et]={k:1,s:stageIndex};saveIndexNow();showIdxPop(def);}
 else{rec.k=(rec.k||0)+1;saveIndexSoon();}
}
function showIdxPop(def){
 let el=document.getElementById('idxPop');
 if(!el){el=document.createElement('div');el.id='idxPop';root.appendChild(el);}
 el.innerHTML='';
 const cv=idxSprite(def,false,44);cv.className='idxPopIc';
 const tx=document.createElement('div'),sm=document.createElement('small'),bb=document.createElement('b');
 sm.textContent=def.boss?'BOSS TERCATAT DI INDEX':'MONSTER TERCATAT DI INDEX';bb.textContent=def.n;
 tx.appendChild(sm);tx.appendChild(bb);el.appendChild(cv);el.appendChild(tx);
 el.classList.toggle('boss',!!def.boss);el.classList.remove('show');void el.offsetWidth;el.classList.add('show');
 clearTimeout(showIdxPop.t);showIdxPop.t=setTimeout(()=>el.classList.remove('show'),3400);
}
function renderIndex(){
 const grid=document.getElementById('idxGrid');if(!grid)return;
 const keep=grid.scrollTop;grid.innerHTML='';
 const c=idxCounts();
 document.getElementById('idxCountNum').textContent=c.all;
 document.getElementById('idxCountTot').textContent='/ '+c.tot;
 document.getElementById('idxBarM').style.width=(c.m/c.mt*100)+'%';
 document.getElementById('idxBarB').style.width=(c.b/c.bt*100)+'%';
 document.getElementById('idxTxtM').textContent=c.m+' / '+c.mt;
 document.getElementById('idxTxtB').textContent=c.b+' / '+c.bt;
 const frag=document.createDocumentFragment();
 for(let s=0;s<STAGES.length;s++){
  const ids=[];
  for(let i=s*5;i<s*5+5&&i<ET.length;i++){
   const d=ET[i],f=!!indexData[i];
   if(idxFilter==='monster'&&d.boss)continue;
   if(idxFilter==='boss'&&!d.boss)continue;
   if(idxFilter==='found'&&!f)continue;
   if(idxFilter==='locked'&&f)continue;
   ids.push(i);
  }
  if(!ids.length)continue;
  const found=ids.filter(i=>indexData[i]).length;
  const grp=document.createElement('section');grp.className='idxGroup';grp.id='idxG'+s;
  const hd=document.createElement('div');hd.className='idxGroupHead';
  const l=document.createElement('span');l.textContent='STAGE '+(s+1)+' · '+STAGES[s].mapName.toUpperCase();
  const r=document.createElement('b');r.textContent=found+'/'+ids.length;
  hd.appendChild(l);hd.appendChild(r);grp.appendChild(hd);
  const row=document.createElement('div');row.className='idxRow';
  for(const i of ids){
   const d=ET[i],rec=indexData[i],f=!!rec;
   const card=document.createElement('button');card.type='button';card.className='idxCard'+(d.boss?' boss':'')+(f?' found':' locked');
   const tag=document.createElement('i');tag.className='idxTag';tag.textContent=d.boss?'BOSS':'MON';card.appendChild(tag);
   const wrap=document.createElement('div');wrap.className='idxSpr';wrap.appendChild(idxSprite(d,!f,72));card.appendChild(wrap);
   const nm=document.createElement('div');nm.className='idxName';nm.textContent=f?d.n:'???';card.appendChild(nm);
   const sub=document.createElement('div');sub.className='idxSub';sub.textContent=f?('Dikalahkan ×'+rec.k):'Belum ditemukan';card.appendChild(sub);
   card.addEventListener('click',()=>showIdxDetail(i));
   row.appendChild(card);
  }
  grp.appendChild(row);frag.appendChild(grp);
 }
 if(!frag.childNodes.length){const em=document.createElement('div');em.className='idxEmpty';em.textContent='Belum ada entri pada filter ini. Kalahkan monster dan boss untuk mengisinya!';frag.appendChild(em);}
 grid.appendChild(frag);grid.scrollTop=keep;
}
function showIdxDetail(i){
 const d=ET[i],rec=indexData[i],f=!!rec,box=document.getElementById('idxDetail');
 box.innerHTML='';box.classList.add('open');box.classList.toggle('boss',!!d.boss);
 const card=document.createElement('div');card.className='idxDCard';
 const spr=document.createElement('div');spr.className='idxDSpr';const cv=idxSprite(d,!f,112);spr.appendChild(cv);
 const info=document.createElement('div');info.className='idxDInfo';
 const t=document.createElement('div');t.className='idxDType';t.textContent=(d.boss?'👑 BOSS':(PAT_ICON[d.p]||'👾')+' MONSTER')+' · STAGE '+(d.si+1);
 const nm=document.createElement('div');nm.className='idxDName';nm.textContent=f?d.n:'???';
 const hab=document.createElement('div');hab.className='idxDHab';hab.textContent='Habitat: '+STAGES[d.si].mapName;
 const lore=document.createElement('p');lore.textContent=f?((d.boss?'Penjaga stage '+(d.si+1)+'. ':'')+(PAT_LORE[d.p]||'Makhluk misterius dari dunia Eclipse.')):'Kalahkan makhluk ini untuk membuka datanya. Petunjuk: ia bisa ditemui di '+STAGES[d.si].mapName+'.';
 info.appendChild(t);info.appendChild(nm);info.appendChild(hab);info.appendChild(lore);
 if(f){
  const st=document.createElement('div');st.className='idxDStats';
  const rows=[['HP DASAR',d.hp],['ATK DASAR',d.atk],['KECEPATAN',d.spd],['XP',d.xp],['GOLD',d.g],['DIKALAHKAN','×'+rec.k]];
  for(const [a,b] of rows){const x=document.createElement('div');const s1=document.createElement('span'),s2=document.createElement('b');s1.textContent=a;s2.textContent=String(b);x.appendChild(s1);x.appendChild(s2);st.appendChild(x);}
  info.appendChild(st);
 }
 const cl=document.createElement('button');cl.type='button';cl.className='idxDClose';cl.textContent='TUTUP';cl.addEventListener('click',()=>box.classList.remove('open'));
 card.appendChild(spr);card.appendChild(info);card.appendChild(cl);box.appendChild(card);
}
function openIndex(from){
 idxReturn=from||'start';idxFilter='all';
 document.querySelectorAll('#idxTabs button').forEach(b=>b.classList.toggle('active',b.dataset.f==='all'));
 document.getElementById('idxDetail').classList.remove('open');
 const sel=document.getElementById('idxJump');
 if(sel&&!sel.options.length){const o0=document.createElement('option');o0.value='';o0.textContent='Lompat ke stage…';sel.appendChild(o0);for(let s=0;s<STAGES.length;s++){const o=document.createElement('option');o.value=s;o.textContent='Stage '+(s+1)+' · '+STAGES[s].mapName;sel.appendChild(o);}}
 if(sel)sel.value='';
 renderIndex();showScreen('indexScreen');
 if(!ENEMY_ATLAS.sprites.length)setTimeout(()=>{if(document.getElementById('indexScreen').classList.contains('active'))renderIndex();},500);
}
document.getElementById('toIndex').addEventListener('click',()=>openIndex('start'));
document.getElementById('pauseIndex').addEventListener('click',()=>openIndex('pauseScreen'));
document.getElementById('indexBack').addEventListener('click',()=>{showScreen(idxReturn||'start');});
document.getElementById('idxTabs').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;idxFilter=b.dataset.f;document.querySelectorAll('#idxTabs button').forEach(x=>x.classList.toggle('active',x===b));renderIndex();});
document.getElementById('idxJump').addEventListener('change',e=>{const v=e.target.value;if(v==='')return;const el=document.getElementById('idxG'+v);if(el)el.scrollIntoView({block:'start',behavior:'smooth'});});
addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('indexScreen').classList.contains('active')){e.stopImmediatePropagation();const dt=document.getElementById('idxDetail');if(dt.classList.contains('open'))dt.classList.remove('open');else document.getElementById('indexBack').click();}},true);
loadIndex();

