 const key=idx+':'+v.k,hit=TEX.get(key);if(hit)return hit;
 const [w,h]=PIP.n[idx],cl=PIP.cell,sx=(idx%PIP.cols)*cl,sy=Math.floor(idx/PIP.cols)*cl;
